window.ScripturaLexicons.BDAG_PART_0287 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-01\" data-source=\"BDAG\" data-search=\"πίναξ, ακος, ὁ substantivo masculino bandeja; travessa; prato grande BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πίναξ, ακος, ὁ</td><td>substantivo masculino</td><td>bandeja; travessa; prato grande</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-02\" data-source=\"BDAG\" data-search=\"πίνω verbo beber; beber de um cálice; passar por provação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πίνω</td><td>verbo</td><td>beber; beber de um cálice; passar por provação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-03\" data-source=\"BDAG\" data-search=\"Πιόνιος, ου, ὁ nome próprio masculino Piônio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πιόνιος, ου, ὁ</td><td>nome próprio masculino</td><td>Piônio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-04\" data-source=\"BDAG\" data-search=\"πιότης, τητος, ἡ substantivo feminino oleosidade; gordura; seiva rica BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πιότης, τητος, ἡ</td><td>substantivo feminino</td><td>oleosidade; gordura; seiva rica</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-05\" data-source=\"BDAG\" data-search=\"πιπράσκω verbo vender; vender como escravo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πιπράσκω</td><td>verbo</td><td>vender; vender como escravo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-06\" data-source=\"BDAG\" data-search=\"πίπτω verbo cair; desabar; prostrar-se; perecer; perder a condição BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πίπτω</td><td>verbo</td><td>cair; desabar; prostrar-se; perecer; perder a condição</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-07\" data-source=\"BDAG\" data-search=\"Πισιδία, ας, ἡ nome próprio feminino Pisídia, região montanhosa da Ásia Menor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πισιδία, ας, ἡ</td><td>nome próprio feminino</td><td>Pisídia, região montanhosa da Ásia Menor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-08\" data-source=\"BDAG\" data-search=\"Πισίδιος, ία, ιον adjetivo pisídio; da Pisídia BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πισίδιος, ία, ιον</td><td>adjetivo</td><td>pisídio; da Pisídia</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-09\" data-source=\"BDAG\" data-search=\"πιστεύω verbo acreditar; confiar; entregar em confiança BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πιστεύω</td><td>verbo</td><td>acreditar; confiar; entregar em confiança</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-10\" data-source=\"BDAG\" data-search=\"πιστικός, ή, όν adjetivo genuíno; puro; de qualidade especial BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πιστικός, ή, όν</td><td>adjetivo</td><td>genuíno; puro; de qualidade especial</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-11\" data-source=\"BDAG\" data-search=\"πίστις, εως, ἡ substantivo feminino fidelidade; compromisso; confiança; fé; doutrina BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πίστις, εως, ἡ</td><td>substantivo feminino</td><td>fidelidade; compromisso; confiança; fé; doutrina</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-12\" data-source=\"BDAG\" data-search=\"πιστός, ή, όν adjetivo confiável; fiel; digno de fé; crente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πιστός, ή, όν</td><td>adjetivo</td><td>confiável; fiel; digno de fé; crente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-13\" data-source=\"BDAG\" data-search=\"πιστόω verbo mostrar fidelidade; estar convencido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πιστόω</td><td>verbo</td><td>mostrar fidelidade; estar convencido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-14\" data-source=\"BDAG\" data-search=\"πιστῶς advérbio fielmente; de maneira confiável BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πιστῶς</td><td>advérbio</td><td>fielmente; de maneira confiável</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-15\" data-source=\"BDAG\" data-search=\"πίων, πῖον adjetivo gordo; bem nutrido BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πίων, πῖον</td><td>adjetivo</td><td>gordo; bem nutrido</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-16\" data-source=\"BDAG\" data-search=\"πλανάω verbo desviar; desencaminhar; enganar-se; errar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλανάω</td><td>verbo</td><td>desviar; desencaminhar; enganar-se; errar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-17\" data-source=\"BDAG\" data-search=\"πλάνη, ης, ἡ substantivo feminino erro; ilusão; engano; desvio da verdade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλάνη, ης, ἡ</td><td>substantivo feminino</td><td>erro; ilusão; engano; desvio da verdade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-18\" data-source=\"BDAG\" data-search=\"πλάνης, ητος, ὁ substantivo masculino errante; vagabundo; equivalente a πλανήτης BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλάνης, ητος, ὁ</td><td>substantivo masculino</td><td>errante; vagabundo; equivalente a πλανήτης</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-19\" data-source=\"BDAG\" data-search=\"πλανήτης, ου, ὁ substantivo masculino errante; astro errante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλανήτης, ου, ὁ</td><td>substantivo masculino</td><td>errante; astro errante</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0287-20\" data-source=\"BDAG\" data-search=\"πλάνος, ον adjetivo e substantivo enganador; sedutor; impostor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πλάνος, ον</td><td>adjetivo e substantivo</td><td>enganador; sedutor; impostor</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0287-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πίναξ, ακος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πίναξ</span>, <span class=\"greek\">ακος</span>, <span class=\"greek\">ὁ</span> (em vários sentidos desde Hom.; inscrições [por exemplo, SEG XLIII, 773, 31s.: II a.C., acerca de um retrato pintado em tabuinha de madeira], papiros; Ath. 17, 2), prato grande relativamente plano, travessa, bandeja, prato (Hom. e outros; BGU 781 V, 16; StudPal 67, 22; Jos., Bell. 5, 562, Ant. 8, 91; empréstimo no rabínico). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πίνακι</span> «sobre uma bandeja» (veja <span class=\"greek\">φέρω</span> 2a<span class=\"greek\">α</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:8</a>, 11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:25</a>, 28. Com <span class=\"greek\">ποτήριον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.11.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 11:39</a>.—B. 345; 599. DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πίνω</span> (Hom.+), imperfeito <span class=\"greek\">ἔπινον</span>; futuro <span class=\"greek\">πίομαι</span> (W-S. 13, 6; 17; B-D-F §74, 2; 77; Rob. 354), 2.ª pessoa do singular <span class=\"greek\">πίεσαι</span> (Ruth 2:9; B-D-F §87; Thackeray p. 218; 282; Rob. 340; Mlt-H. 198); 2.º aoristo <span class=\"greek\">ἔπιον</span> (sobre <span class=\"greek\">ἔπιαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:4</a> D, veja B-D-F §81, 3; Mlt-H. 208), imperativos <span class=\"greek\">πίε</span>, <span class=\"greek\">πιέτω</span>, infinitivo <span class=\"greek\">πιεῖν</span> (editores preferem a contração <span class=\"greek\">πεῖν</span> [<span class=\"greek\">πῖν</span>]; veja B-D-F §101 p. 48; §31, 2; W-S. §5, 23b; Rob. 72; 204; Mayser 365; Thackeray p. 63s.; W-H., apêndice 170); perfeito <span class=\"greek\">πέπωκα</span>; mais-que-perfeito, 3.ª pessoa do singular <span class=\"greek\">πεπώκει</span> 1 Km 30:12 (W-S. §13, 15; B-D-F §83, 1).<br>① Ingerir um líquido, beber, com acusativo daquilo que se bebe: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:29</a>. <span class=\"greek\">αἷμα</span> «sangue» (Num 23:24; 1 Ch 11:19 e outros; 4 [6] Esdr [POxy 1010]): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.53\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:53</a>s., 56 (cf. a imagem em Jos., Bell. 5, 344 <span class=\"greek\">ἐσθίειν</span> … <span class=\"greek\">καὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πόλεως</span> <span class=\"greek\">αἷμα</span> <span class=\"greek\">πίνειν</span>). <span class=\"greek\">οἶνον</span> «vinho» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:15</a> (cf. Dt 29:5); 5:39; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:29b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:21</a> (Is 22:13) e outros. <span class=\"greek\">τί</span> <span class=\"greek\">πίωμεν</span>; «que beberemos?» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:31</a>. <span class=\"greek\">φαγεῖν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πιεῖν</span> <span class=\"greek\">ὅσον</span> <span class=\"greek\">ἄν</span> <span class=\"greek\">βούλωνται</span> «comer e beber quanto quiserem» MPol 7:2. <span class=\"greek\">ἐσθίειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πίνειν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span> «comer e beber o que alguém põe diante deles» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:7</a>.<br>Seguido de <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, «beber de alguma coisa» (Ctesias: 688 Fgm. 1l<span class=\"greek\">β</span> p. 433 Jac. [Sotion Fgm. 17 em <span class=\"greek\">Παραδοξογράφοι</span> W. p. 185], <span class=\"greek\">π</span>. <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτῆς</span> [uma fonte], resultando na confissão de atos cometidos em segredo; Ael. Aristid. 39, 4 K. = 18 p. 409 D.; Jer 28:7; GrBar 4:6; Just., D. 140, 1), 22:18. <span class=\"greek\">μηδεὶς</span> <span class=\"greek\">φαγέτω</span> <span class=\"greek\">μηδὲ</span> <span class=\"greek\">πιέτω</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εὐχαριστίας</span> «ninguém coma nem beba da eucaristia» D 9:5.<br>Seguido de <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, «beber de algo» (Gen 9:21; TestJos 19:5; GrBar 5:2; Syntipas p. 43, 15 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δηλητηρίου</span> <span class=\"greek\">πίομαι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:29a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:25a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:13</a>s. Com acusativo do recipiente do qual se bebe, caso em que se identificam recipiente e conteúdo (<span class=\"greek\">ποτήριον</span> a): <span class=\"greek\">ποτήριον</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">πίνειν</span> «beber o cálice do Senhor» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:21</a>; cf. 11:26s.<br>O recipiente também pode ser introduzido por <span class=\"greek\">ἐκ</span> (Hipponax [VI a.C.] 16 e 17 D.2; Aristoph., Equ. 1289; Pla., Rep. 417a; X., An. 6, 1, 4 <span class=\"greek\">ἐκ</span> <span class=\"greek\">ποτηρίων</span>; SIG 1168, 80): <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ποτηρίου</span> <span class=\"greek\">πινέτω</span> «beba do cálice» (veja 2 Km 12:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.28\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:28</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:23</a>. Semelhantemente, <span class=\"greek\">ἐξ</span> <span class=\"greek\">αὐτοῦ</span> (= <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φρέατος</span>.—Paus. Attic. <span class=\"greek\">κ</span>, 56 <span class=\"greek\">κρήνη</span>, <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἧς</span> <span class=\"greek\">ἔπινον</span>; Num 21:22; Philo, Deus Imm. 155), «dele» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:12</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">πέτρας</span> «da rocha» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:4b</a>.—Sobre o acusativo <span class=\"greek\">κρίμα</span> <span class=\"greek\">ἑαυτῷ</span> <span class=\"greek\">ἐσθίει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πίνει</span> 11:29b, cf. <span class=\"greek\">κρίμα</span> 4b.<br>Em uso absoluto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:34b</a>. Com <span class=\"greek\">ἐσθίειν</span>: 11:18s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:33</a>; 12:19 (Phoenix Col. 1, 9 [Coll. Alex. p. 231]), 45 e outros; cf. 17:8 (sobre o protocolo em 17:7, cf. ViAesopi G 61 P.). <span class=\"greek\">ἔφαγεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔπιεν</span> «comeu e bebeu» 1 Cl 3:1 (cf. Dt 32:15); I Tr 9:1. <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φαγεῖν</span> <span class=\"greek\">οὔτε</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πεῖν</span> (= <span class=\"greek\">πιεῖν</span>) «nem para comer nem para beber» AcPl Ox 6, 7s. (= Aa 1, 241, 12s.). <span class=\"greek\">τρώγειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:38</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:32</a>. <span class=\"greek\">ἐσθίειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">π</span>. <span class=\"greek\">μετά</span> <span class=\"greek\">τινος</span> «comer e beber com alguém» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:49</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:16</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:30</a>.<br><span class=\"greek\">δοῦναί</span> <span class=\"greek\">τινι</span> <span class=\"greek\">πιεῖν</span> (<span class=\"greek\">τι</span>), «dar de beber (algo) a alguém» (numerosos exemplos de <span class=\"greek\">δοῦναι</span> <span class=\"greek\">πιεῖν</span> em AKnox e WHeadlam, Herodas 1922 p. 55s.; Jos., Ant. 2, 64) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:34a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:23</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:7</a> (<span class=\"greek\">δὸς</span> <span class=\"greek\">πεῖν</span> como em POxy 1088, 55 [I d.C.] e Cyranides p. 49, 16. Cf. Lamellae Aur. Orphicae ed. AOlivieri 1915 p. 12 <span class=\"greek\">σοι</span> <span class=\"greek\">δώσουσι</span> <span class=\"greek\">πιεῖν</span> <span class=\"greek\">θείης</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">κρήνης</span> [IV/III a.C.]), v. 10. <span class=\"greek\">πῶς</span> <span class=\"greek\">παρ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">πεῖν</span> <span class=\"greek\">αἰτεῖς</span> «como podes pedir-me de beber?» v. 9.<br>Figuradamente, acerca da terra: <span class=\"greek\">γῆ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πιοῦσα</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὑετόν</span> «a terra que bebe a chuva» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:7</a> (essa figura e expressões correspondentes nos trágicos e outros; cf. Hdt. 3, 117; 4, 198; Anacreontea 21, 1; Dt 11:11; SibOr 3, 696). Em João, Jesus convida os sedentos a beber a água que ele lhes oferece para não mais sentirem sede (cf. Lucian, Dial. Deor. 4, 5 <span class=\"greek\">πίνειν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀθανασίας</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:14</a>; 7:37.<br>② Na expressão idiomática <span class=\"greek\">πιεῖν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ποτήριον</span>, com palavras adicionais que esclarecem o sentido, «beber o cálice» = submeter-se a dura provação ou à morte (<span class=\"greek\">ποτήριον</span> b), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:22</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:38</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:11</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:42</a>; ApcPt Rainer 16 (sobre o uso figurado, cf. Herodas 1, 25 <span class=\"greek\">π</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">καινῆς</span>, «do cálice novo»; e, como <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:22</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 10:38</a>s. a respeito dos que sofrem o mesmo destino: Aristoph., Eq. 1289 <span class=\"greek\">οὔποτ</span>’ <span class=\"greek\">ἐκ</span> <span class=\"greek\">ταὐτοῦ</span> <span class=\"greek\">μεθ</span>’ <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">πίεται</span> <span class=\"greek\">ποτηρίου</span> = «jamais beberá conosco do mesmo cálice»; Libanius, Ep. 355, 4 F. <span class=\"greek\">μνήμη</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">ταὐτοῦ</span> <span class=\"greek\">κρατῆρος</span> <span class=\"greek\">πεπωκότων</span>).<br>Semelhantemente, <span class=\"greek\">πίεται</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οἴνου</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θυμοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> «beberá do vinho da ira de Deus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:10</a>; cf. 18:3 (sobre a leitura, veja RBorger, TRu 52, ’87, 50s.; <span class=\"greek\">θυμός</span> 1; 2; cf. com acusativo <span class=\"greek\">τρώγειν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τὸν</span> <span class=\"greek\">λόγον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span>, <span class=\"greek\">τὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀθανασίας</span> <span class=\"greek\">ἄρτον</span> Iren. 4, 38, 1 [Harv. II 293, 12]).—B. 331. DELG s.v. <span class=\"greek\">πίνω</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πιόνιος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πιόνιος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span>, Piônio, um dos que reuniram e editaram os relatos do martírio de Policarpo, MPol 22:3; EpilMosq 5.—PCorssen, ZNW 5, 1904, 266ss.; ESchwartz, De Pionio et Polycarpo, programa, Göttingen 1905.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιότης, τητος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πιότης</span>, <span class=\"greek\">τητος</span>, <span class=\"greek\">ἡ</span> (Hippocr.; LXX, Philo), estado de ser oleoso, oleosidade, gordura. O uso do termo em relação a plantas (Theophr., HP 9, 1, 3; cf. Jos., Bell. 3, 516 sobre a fertilidade da região do lago de Genesaré) aparece na imagem em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:17</a>: <span class=\"greek\">ἡ</span> <span class=\"greek\">ῥίζα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πιότητος</span> «a raiz com sua riqueza oleosa», isto é, sua «seiva» = «a raiz com sua seiva rica» (REB: «partilham a mesma raiz e seiva da oliveira») da oliveira cultivada (cf. Judg 9:9; TestLevi 8:8; TestIss 5:5. Uma vez que o azeite é o produto apreciado da oliveira, a raiz é descrita como sua fonte).—DELG s.v. <span class=\"greek\">πίαρ</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιπράσκω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πιπράσκω</span> (Aeschyl., Hdt.+.—B-D-F §101 p. 48; veja Mlt-H. 254), imperfeito <span class=\"greek\">ἐπίπρασκον</span>; perfeito <span class=\"greek\">πέπρακα</span> (em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:46</a> e Hv 1, 1, 1 possui valor aspectual de aoristo; veja B-D-F §343, 1; Rob. 900). Passivo: futuro <span class=\"greek\">πραθήσομαι</span> LXX; 1.º aoristo <span class=\"greek\">ἐπράθην</span>; particípio perfeito <span class=\"greek\">πεπραμένος</span>. Envolver-se em venda, vender, com acusativo da coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.45\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:45</a>. Passivo: 4:34; 5:4. Com genitivo do preço (Isaeus 7, 31; Lysias 18:20; Dt 21:14), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.5\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:5</a>; <span class=\"greek\">πραθῆναι</span> <span class=\"greek\">ἐπάνω</span> <span class=\"greek\">δηναρίων</span> <span class=\"greek\">τριακοσίων</span> «ser vendido por mais de trezentos denários» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:5</a> (veja <span class=\"greek\">ἐπάνω</span> 2). Com acusativo de pessoa, «vender alguém (como escravo)» Hv 1, 1, 1. Passivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:25</a>. Figuradamente (Ps.-Demosth. 17, 13 <span class=\"greek\">τοῖς</span> <span class=\"greek\">πεπρακόσιν</span> <span class=\"greek\">ἑαυτοὺς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τἀναντία</span> = «àqueles que se venderam ao que é contrário» [aos interesses da pátria]), acerca de pessoa vendida como escrava ao pecado, <span class=\"greek\">πεπραμένος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἁμαρτίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 7:14</a> (semelhantemente 3 Km 20:25; 4 Km 17:17; 1 Macc 1:15 <span class=\"greek\">ἐπράθησαν</span> <span class=\"greek\">ποιῆσαι</span> <span class=\"greek\">πονηρόν</span>).—DELG s.v. <span class=\"greek\">πέρνημι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πίπτω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πίπτω</span> (Hom.+), imperfeito <span class=\"greek\">ἔπιπτον</span>; futuro <span class=\"greek\">πεσοῦμαι</span> (B-D-F §77; Rob. 356); 2.º aoristo <span class=\"greek\">ἔπεσον</span> e <span class=\"greek\">ἔπεσα</span> (B-D-F §81, 3; W-S. §13, 13; Mlt-H. 208; W-H., apêndice p. 164; Tdf., Prol. p. 123); perfeito, 2.ª pessoa do singular <span class=\"greek\">πέπτωκας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:5</a> (<span class=\"greek\">πέπτωκες</span>, variante textual; B-D-F §83, 2; W-S. §13, 16; Mlt-H 221), 3.ª pessoa do plural <span class=\"greek\">πέπτωκαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:3</a>, variante textual (W-S. §13, 15; Mlt-H. 221).<br>① Mover-se com relativa rapidez em direção descendente, cair, correspondendo passivamente à ideia de <span class=\"greek\">βάλλω</span>.<br>ⓐ Cair (de cima) de um ponto elevado, indicando-se o «ponto de origem» por <span class=\"greek\">ἀπό</span> (Hom. e outros): <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τραπέζης</span> «da mesa» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:21</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span> «do céu» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:29</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">κεφαλῆς</span> «da cabeça» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:34</a>, variante textual (queda de cabelos, como em Synes., Calvit. 1, p. 63b). A direção ou o destino da queda é expressa por advérbio: <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τριστέγου</span> <span class=\"greek\">κάτω</span> «do terceiro andar para baixo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:9</a>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κεράμου</span> <span class=\"greek\">χαμαί</span> «do telhado ao chão» Hm 11:20.<br><span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span> «de alguma coisa»: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span> (Sallust. 4 p. 8, 19; Job 1:16; 3 Km 18:38.—SibOr 5, 72 <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἄστρων</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:25</a>; acerca do relâmpago (Ps.-Plut., Vi. Hom. 111 <span class=\"greek\">εἰ</span> <span class=\"greek\">ἐκπίπτοι</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀστράπη</span>; Ps.-Clem., Hom. 9, 5; 6), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:18</a> (Lycophron, v. 363, acerca da imagem de Atena <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">πεσοῦσα</span>. Cf. <span class=\"greek\">σατάν</span>; «ser lançado» também é possível aqui); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:10a</a>; acrescenta-se o destino: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> 9:1 (Ps.-Callisth. 2, 10, 10 <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔδαφος</span> <span class=\"greek\">πεπτωκότες</span>).<br>Quando apenas se indica o destino: <span class=\"greek\">ἐν</span> <span class=\"greek\">μέσῳ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀκανθῶν</span> «entre os espinhos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:7</a>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> «sobre alguma coisa» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:10b</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> (Aeschyl., Ag. 1019; Am 3:5; JosAs 16:16) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:29</a> (com a variante textual patrística <span class=\"greek\">εἰς</span> <span class=\"greek\">παγίδα</span>, cf. Am 3:5 e Aesop, Fab. 193 P.=340 H.//284 Ch.//207 H-H., acerca de um pássaro: <span class=\"greek\">ἐμπίπτειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">βρόχους</span>); 13:8; Hm 11:21 (o «lugar de origem» é indicado pelo advérbio <span class=\"greek\">ἄνωθεν</span>).—<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πετρώδη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:5</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:5</a> (<span class=\"greek\">ἐπί</span> 4b<span class=\"greek\">γ</span>). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀκάνθας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:7</a> (<span class=\"greek\">ἐπί</span> 4b<span class=\"greek\">δ</span>). Uma pessoa cai <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λίθον</span> «sobre a pedra» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:44a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:18a</a>. Inversamente, a pedra cai sobre uma pessoa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:44b</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.18\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:18b</a>. Igualmente, <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> 23:30; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:16</a> (cf. Hos 10:8 para ambos).<br>Na linguagem figurada: <span class=\"greek\">ὁ</span> <span class=\"greek\">ἥλιος</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> «o (calor do) sol cai sobre alguém» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:16</a> (Maximus Tyr. 4, 1a <span class=\"greek\">ἡλίου</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">πίπτον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">γῆν</span>; Alex. Aphr., An. Mant. p. 146, 9 Br. <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">πίπτει</span>). <span class=\"greek\">ὁ</span> <span class=\"greek\">κλῆρος</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> «a sorte recai sobre alguém» (<span class=\"greek\">κλῆρος</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:26</a>. «Sobrevir a alguém», <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>: <span class=\"greek\">ἀχλὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σκότος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:11</a>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:11</a>, variante textual (<span class=\"greek\">φόβος</span> 2a).<br><span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> (Hes., Op. 620), <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> (Phlegon: 257 Fgm. 36, 1, 5 Jac. <span class=\"greek\">πίπτειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:13</a>; 1 Cl 24:5. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδόν</span> «na estrada» Hv 3, 7, 1. <span class=\"greek\">εἰς</span> <span class=\"greek\">βόθυνον</span> «num poço» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:14</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:5</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ἀκάνθας</span> «entre os espinhos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:14</a>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πῦρ</span> «no fogo» Hv 3, 7, 2. <span class=\"greek\">παρά</span> <span class=\"greek\">τι</span> «sobre alguma coisa», <span class=\"greek\">παρὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδόν</span> «à beira do caminho» (Iambl. Erot. p. 222, 22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 4:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:5</a>. <span class=\"greek\">ἐγγύς</span> <span class=\"greek\">τινος</span> «perto de alguma coisa», <span class=\"greek\">ἐγγὺς</span> (<span class=\"greek\">τῶν</span>) <span class=\"greek\">ὑδάτων</span> «perto das águas» Hv 3, 2, 9; 3, 7, 3.<br>ⓑ Acerca daquilo que, até pouco antes, estava de pé, cair, desabar, despedaçar-se.<br><span class=\"greek\">α</span>. Acerca de pessoas.<br><span class=\"hebrew\" dir=\"rtl\">א</span>. Cair ao chão, cair (violentamente): <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὕδωρ</span> «no fogo e na água» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:15</a> (mas HZimmern, Die Keilinschriften u. d. AT3 1903, 366; 363s., e JWeiss ad loc. interpretam a queda no fogo e na água como febre e calafrios). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> (SibOr 4, 110; 5, 100) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:20</a> (<span class=\"greek\">π</span>. sob influência de espírito hostil; semelhantemente Jos., Ant. 8, 47). <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> (SibOr 4, 110, variante textual) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:4</a>; cf. 22:7 (veja <span class=\"greek\">ἔδαφος</span>). <span class=\"greek\">χαμαί</span> (Job 1:20; Philo, Agr. 74) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 18:6</a>. <span class=\"greek\">ἔπεσα</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">νεκρός</span> «caí a seus pés como morto» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:17</a>.<br>Em uso absoluto, «cair» GPt 5:18, variante textual. «Cair morto» (Paradox. Vat. 37 Keller <span class=\"greek\">πίπτει</span>; Mel., P. 26, 184 <span class=\"greek\">πρηνὴς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">ἔπιπτε</span> <span class=\"greek\">σιγῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:5</a>, 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:8</a> (cf. Ex 32:28); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:17</a> (Num 14:29). Especificamente, «cair em batalha» (Ael. Aristid. 46 p. 233 D.; Appian, Hann. 56 §236; Jos., Vi. 341; 354) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:24</a> (cf. <span class=\"greek\">στόμα</span> 4 e Sir 28:18; 4 [6] Esdr [POxy 1010, 3–11 <span class=\"greek\">σὺ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ῥομφαίᾳ</span> <span class=\"greek\">πεσῇ</span> … <span class=\"greek\">πεσοῦνται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">μαχαίρῃ</span>]).<br><span class=\"hebrew\" dir=\"rtl\">ב</span>. Prostrar-se, lançar-se ao chão como sinal de devoção ou humildade diante de pessoas de posição elevada ou seres divinos, especialmente ao aproximar-se com uma súplica (LXX; TestAbr A 18 p. 100, 29 [Stone p. 48]; JosAs 14:4; ApcSed 14:2), em uso absoluto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:11</a>; 4:9; 18:26, 29; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 5:14</a>; 19:4; 22:8 (em todas essas passagens [exceto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:29</a>], <span class=\"greek\">π</span>. está estreitamente ligado a <span class=\"greek\">προσκυνεῖν</span> [como em Jos., Ant. 10, 213, após Da 3:5, e ApcMos 27]. Igualmente em muitas passagens já mencionadas).<br>Com expressões adicionais diversas (Jos., Ant. 10, 11 <span class=\"greek\">πεσὼν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἱκέτευε</span>; Gen 17:3, 17; Num 14:5): <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πρόσωπον</span> (<span class=\"greek\">αὐτοῦ</span>, <span class=\"greek\">αὐτῶν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:6</a>; 26:39; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:12</a>; 17:16 (<span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πρόσωπον</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">αὐτοῦ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:25</a>; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πρόσωπα</span> <span class=\"greek\">αὐτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:11</a>; 11:16; <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:35</a>.<br>Ademais, aquele a quem se presta devoção pode ser acrescentado de várias maneiras: <span class=\"greek\">ἐνώπιόν</span> <span class=\"greek\">τινος</span> (cf. 2 Km 3:34) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:10</a>; 5:8; 7:11. <span class=\"greek\">ἔμπροσθεν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ποδῶν</span> <span class=\"greek\">τινος</span> 19:10. <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">τινός</span> (Diog. L. 2, 79) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:29</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:32</a>, variante textual. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:25</a> (variante textual acrescenta <span class=\"greek\">αὐτοῦ</span>). <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">τινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.41\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:41</a>; 17:16 (veja acima). <span class=\"greek\">πρὸς</span> <span class=\"greek\">τοὺς</span> <span class=\"greek\">πόδας</span> <span class=\"greek\">τινός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.32\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:25</a> D; Hv 3, 2, 3.<br><span class=\"greek\">β</span>. Acerca de coisas, especialmente estruturas, cair, desmoronar, desabar (Appian, Iber. 54 §228; Jos., C. Ap. 1, 192, Ant. 16, 18): sobre a <span class=\"greek\">σκηνὴ</span> <span class=\"greek\">Δαυίδ</span> (<span class=\"greek\">σκηνή</span>, final), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:16</a> (Am 9:11). Acerca de casa, «cair, ruir» (Diod S 11, 63, 2 <span class=\"greek\">τῶν</span> <span class=\"greek\">οἰκιῶν</span> <span class=\"greek\">πιπτουσῶν</span>; Dio Chrys. 6, 61; 30 [47], 25; Aristeas Hist.: 725 Fgm. 1, 3 Jac. [em Eus., PE 9, 25, 3]; Job 1:19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:25</a>, 27; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:49</a>, variante textual (Diod S 15, 12, 2 <span class=\"greek\">τῶν</span> <span class=\"greek\">οἰκιῶν</span> <span class=\"greek\">πιπτουσῶν</span> devido ao afluxo do <span class=\"greek\">ποταμός</span>). <span class=\"greek\">τὰ</span> <span class=\"greek\">τείχη</span> <span class=\"greek\">Ἰεριχὼ</span> <span class=\"greek\">ἔπεσαν</span> «caíram as muralhas de Jericó» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.30\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:30</a> (cf. Josh 6:5, 20.—Appian, Bell. Civ. 1, 112 §524; Ael. Aristid. 25, 42 K. = 43 p. 813 D.: <span class=\"greek\">τὰ</span> <span class=\"greek\">τείχη</span> <span class=\"greek\">π</span>.). <span class=\"greek\">ἐφ</span>’ <span class=\"greek\">οὓς</span> <span class=\"greek\">ἔπεσεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πύργος</span> «sobre os quais caiu a torre» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:4</a> (sobre <span class=\"greek\">πύργος</span>: X., Hell. 5, 2, 5; Arrian, Anab. 6, 7, 5; Polyaenus 6, 50; Jos., Bell. 5, 292; SibOr 11, 12.—<span class=\"greek\">π</span>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span> Job 1:19). <span class=\"greek\">οἶκος</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">οἶκον</span> <span class=\"greek\">πίπτει</span> «uma casa cai sobre outra» 11:17 (Jülicher, Gleichn. 221s.). Acerca de cidade (Oenomaus em Eus., PE 5, 25, 6) Ox 1, 18s. (= GTh 32); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:13</a>; 16:19.<br>Figuradamente, «tornar-se inválido, terminar, falhar» (Pla., Euthyphr. 14d; Philostrat., Ep. 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:17</a> (cf. Josh 23:14, variante textual; Ruth 3:18); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:8</a>.<br>② Sofrer perda de posição ou condição, cair, ser destruído, em extensão de 1.<br>ⓐ Cair, ser destruído: <span class=\"greek\">ἔπεσεν</span>, <span class=\"greek\">ἔπεσεν</span> <span class=\"greek\">Βαβυλών</span> «caiu, caiu Babilônia» (<span class=\"greek\">Β</span>., Babilônia como símbolo da humanidade oposta a Deus e a seu povo; cf. Is 21:9; Jer 28:8.; Just., D. 49, 8. A repetição do verbo serve à ênfase, como Sappho, Fgm. 131 D.2 <span class=\"greek\">οὔκετι</span> <span class=\"greek\">ἴξω</span> … <span class=\"greek\">οὔκετι</span> <span class=\"greek\">ἴξω</span> [Campbell 114 p. 138: <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">ἤξω</span> … <span class=\"greek\">οὐκέτι</span> <span class=\"greek\">ἤξω</span>]; Aristoph., Equ. 247; M. Ant. 5, 7; Ps.-Libanius, Char. Ep. p. 33, 5 <span class=\"greek\">ἐρῶ</span>, <span class=\"greek\">ἐρῶ</span>. Destina-se a remover qualquer possibilidade de dúvida, como Theod. Prodr. 5, 66 <span class=\"greek\">εἶδον</span>, <span class=\"greek\">εἶδον</span> = «realmente vi»; Theocr. 14, 24 <span class=\"greek\">ἔστι</span> <span class=\"greek\">Λύκος</span>, <span class=\"greek\">Λύκος</span> <span class=\"greek\">ἐστί</span> = «é realmente um lobo»; em Apocalipse, o foco está no lamento; veja as referências em Schwyzer II 60), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:8</a>; 18:2.<br>ⓑ Cair num sentido transcendente ou moral, arruinar-se completamente (Polyb. 1, 35, 5; Diod S 13, 37, 5; Pr 11:28; Sir 1:30; 2:7; TestGad 4:3) = «cair de um estado de graça» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 11:11</a> (figuradamente com <span class=\"greek\">πταίω</span> [veja esse verbete 1]), 22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:11</a> (talvez em referência ao juízo final). Em sentido menos grave, «desviar-se moralmente»: <span class=\"greek\">τοὺς</span> <span class=\"greek\">πεπτωκότας</span> <span class=\"greek\">ἔγειρον</span> «levantai os que caíram» 1 Cl 59:4. No jogo de palavras «estar em pé e cair» (cf. Pr 24:16), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:12</a>; 2 Cl 2:6. <span class=\"greek\">μνημόνευε</span> <span class=\"greek\">πόθεν</span> <span class=\"greek\">πέπτωκες</span> «lembra-te da altura de que caíste» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:5</a>.<br>ⓒ <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">κρίσιν</span> <span class=\"greek\">π</span>. «cair sob condenação» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:12</a> (sobre <span class=\"greek\">π</span>. <span class=\"greek\">ὑπό</span> <span class=\"greek\">τι</span>, cf. Diod S 4, 17, 5 <span class=\"greek\">π</span>. <span class=\"greek\">ὑπ</span>’ <span class=\"greek\">ἐξουσίαν</span> [Just., D. 105, 4]; Herodian 1, 4, 2; 2 Km 22:39; Tat. 8, 2 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">εἱμαρμένην</span>; Hippol., Ref. 4, 3, 5 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπίσκεψιν</span>, «cair sob escrutínio»; Did., Gen. 211, 5 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">κατάραν</span>; Theoph. Ant. 2, 25 [p. 162, 12] <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">θάνατον</span>).<br>ⓓ <span class=\"greek\">π</span>. … <span class=\"greek\">εἰς</span> <span class=\"greek\">νόσον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔσχατον</span> <span class=\"greek\">κίνδυνον</span> «cair em enfermidade e extremo perigo» AcPl Ha 4, 15.<br>ⓔ Cair, perecer (Philo, Aet. M. 128): <span class=\"greek\">πίπτοντος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰσραήλ</span> «quando Israel cai» B 12:5. <span class=\"greek\">οἱ</span> <span class=\"greek\">πέντε</span> <span class=\"greek\">ἔπεσαν</span> «cinco pereceram, desapareceram, deixaram a cena» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:10</a> (cf. também <span class=\"greek\">π</span>. = «morrer» Job 14:10).—B. 671. DELG. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πισιδία, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πισιδία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (Diod S 33, 5a; Strabo 12, 8, 14 <span class=\"greek\">Ἀντιόχεια</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">Πισιδίᾳ</span>; Ptolemaeus 5, 4, 11; 5, 5, 4; OGI 535, 5 e outros casos em inscrições), Pisídia, região montanhosa do interior da Ásia Menor, a oeste dos montes Tauro, atravessada por Paulo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:24</a>. <span class=\"greek\">Ἀντιόχεια</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Πις</span>. 13:14, variante textual.—Zahn, Einl.3 I 130ss.; VSchultze, Altchristl. Städte und Landschaften II 2, 1926; Hemer, Acts 228; Pauly-W. XX 1793–97; Kl. Pauly IV 868s.; BHHW III 1475s. Veja também <span class=\"greek\">Παμφυλία</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πισίδιος, ία, ιον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πισίδιος</span>, <span class=\"greek\">ία</span>, <span class=\"greek\">ιον</span>, pisídio, «da Pisídia»: <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἀντιόχειαν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Πισιδίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:14</a>. Mas, como o adjetivo <span class=\"greek\">Πισίδιος</span> não ocorre em nenhum outro lugar (veja também FBlass ad loc.) e «pisídio» é preferencialmente expresso por <span class=\"greek\">Πισιδικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Diod S 18, 25, 6; 18, 44, 1; 18, 45, 3.—Strabo refere-se a essa Antioquia como situada <span class=\"greek\">πρὸς</span> (<span class=\"greek\">τῇ</span>) <span class=\"greek\">Πισιδίᾳ</span> 12, 3, 31; 12, 6, 4; 12, 8, 14), essa forma provavelmente deve ser abandonada em favor da variante textual <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἀντιόχειαν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Πισιδίας</span>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιστεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πιστεύω</span> (trágicos+), imperfeito <span class=\"greek\">ἐπίστευον</span>; 1.º aoristo <span class=\"greek\">ἐπίστευσα</span>; perfeito <span class=\"greek\">πεπίστευκα</span>; mais-que-perfeito <span class=\"greek\">πεπιστεύκειν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.23\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:23</a> (sobre a omissão do aumento, veja B-D-F §66, 1; Mlt-H. 190). Passivo: futuro, 3.ª pessoa do plural <span class=\"greek\">πιστευθήσονται</span> Gen 42, 20; 1.º aoristo <span class=\"greek\">ἐπιστεύθην</span>; perfeito <span class=\"greek\">πεπίστευμαι</span>. (A palavra não ocorre em Phlm, 2 Pt, 2 e 3J, Rv, MPol ou D. Mas é especialmente frequente em J e 1J, onde ocorre, respectivamente, 96 e 9 vezes; <span class=\"greek\">πίστις</span> não ocorre no Evangelho de João e ocorre apenas uma vez em 1J, 5:4. Nossa literatura emprega esse verbo predominantemente num sentido transcendente, ou pelo menos com conotação transcendente.)<br>① Considerar alguma coisa verdadeira e, por isso, digna de confiança, acreditar.<br>ⓐ Acreditar em algo, convencer-se de algo, sendo aquilo em que se acredita indicado:<br><span class=\"greek\">α</span>. Pelo acusativo de coisa (Soph., Oed. Rex 646 <span class=\"greek\">τάδε</span>; Aristot., Analyt. Pr. 2, 23, 68b, 13 <span class=\"greek\">ἅπαντα</span>; PSI 494, 14 <span class=\"greek\">μηθέν</span>; UPZ 70, 29 [152/151 a.C.] <span class=\"greek\">π</span>. <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐνύπνια</span>; ApcEsdr 7:12 p. 32, 26 <span class=\"greek\">τὸ</span> <span class=\"greek\">βιβλίον</span> <span class=\"greek\">τοῦτο</span>): <span class=\"greek\">ἡ</span> <span class=\"greek\">ἀγάπη</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">πιστεύει</span> «o amor acredita em tudo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:7</a>. <span class=\"greek\">πεπιστεύκαμεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀγάπην</span> «acreditamos no amor» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:16</a>. <span class=\"greek\">πιστεύεις</span> <span class=\"greek\">τοῦτο</span>; «crês nisto?» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.26\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:26b</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.41\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:41</a> (Hab 1:5). Passivo: <span class=\"greek\">ἐπιστεύθη</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">μαρτύριον</span> <span class=\"greek\">ἡμῶν</span> «nosso testemunho foi acreditado» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:10b</a> (cf. Aristot., EN 10, 2 p. 1172b, 15 <span class=\"greek\">ἐπιστεύοντο</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγοι</span>; Gen 42:20).<br><span class=\"greek\">β</span>. Por oração introduzida por <span class=\"greek\">ὅτι</span>, «acreditar que» (Plut., Mor. 210d; Aelian, VH 1, 16 p. 8, 9; Herm. Wr. 4, 4: Porphyr., Ad Marcellam 24; PLond III, 897, 12 p. 207 [I d.C.]; Tob 10:8 S; Job 9:16; 15:31; 39:12; La 4:12; 4 Macc 7:19; TestAbr A 18 p. 100, 18 [Stone p. 48]; ParJer 6:7; Just., A I, 18, 2 e outros; Orig., C. Cels. 4, 89, 16): <span class=\"greek\">μακαρία</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πιστεύσασα</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἔσται</span> <span class=\"greek\">τελείωσις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.45\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:45</a> (<span class=\"greek\">ὅτι</span> aqui pode significar «pois»: veja <span class=\"greek\">ὅτι</span> 4b).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:23</a>; cf. v. 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:24</a> (<span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐγώ</span> <span class=\"greek\">εἰμι</span>, como Is 43:10); 11:27, 42; 13:19; 14:10; 16:27, 30; 17:8, 21; 20:31a; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:8</a>; 10:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:19a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:1</a>, 5; Hv 3, 8, 4; 4, 2, 4; Hm 1:1; 6, 2, 10b; Hs 2:5.—[<span class=\"greek\">ὅτι</span> <span class=\"greek\">εἷς</span> <span class=\"greek\">θεός</span>] <span class=\"greek\">καὶ</span> <span class=\"greek\">εἷς</span> <span class=\"greek\">χριστός</span> AcPl Ha 1, 17; AcPlCor 1:8. <span class=\"greek\">π</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> <span class=\"greek\">ὅτι</span> «acreditar a respeito de alguém que» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:18</a> (M. Ant. 1, 15, 5 <span class=\"greek\">πιστεύειν</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">λέγοι</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">οὕτως</span> <span class=\"greek\">φρονεῖ</span> «acreditar que aquilo que alguém diz corresponde ao que pensa»; Just., D. 10, 1 <span class=\"greek\">π</span>. <span class=\"greek\">ἡμῶν</span>· <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐσθίομεν</span> <span class=\"greek\">ἀνθρώπους</span>.—<span class=\"greek\">π</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> como Plut., Lyc. 19, 4; Jos., Ant. 14, 267).<br><span class=\"greek\">γ</span>. Pelo acusativo e infinitivo (presente em Pla., Gorg. 524a; PTebt 314, 3 [II d.C.]; 4 Macc 5:25; Jos., C. Ap. 2, 160; Just., A I, 8, 2 e outros; Ath. 20, 3): <span class=\"greek\">πιστεύω</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">υἱὸν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Ἰησοῦν</span> «creio que Jesus é o Filho de Deus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.37\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:37b</a>.—GMary 463, 8.—IRo 10:2. Pelo infinitivo (Thu 2, 22, 1; Job 15:22; AscIs 2:10 <span class=\"greek\">εἰς</span> <span class=\"greek\">οὐρανὸν</span> <span class=\"greek\">ἀναβῆναι</span>): <span class=\"greek\">πιστεύομεν</span> <span class=\"greek\">σωθῆναι</span> «cremos ser salvos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:11</a> (interpretação diferente em JNolland, NTS 27, ’80, 112s.: infinitivo de resultado, «cremos [para] sermos salvos»). Pelo acusativo e particípio: <span class=\"greek\">ἐν</span> <span class=\"greek\">σαρκὶ</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">πιστεύω</span> <span class=\"greek\">ὄντα</span> «creio que ele existiu na carne» ISm 3:1.<br><span class=\"greek\">δ</span>. Pelo dativo de coisa, «dar crédito a, acreditar em» (Aeschyl., Pers. 786 <span class=\"greek\">θεῶν</span> <span class=\"greek\">θεσφάτοισιν</span>; Soph., Phil. 1374 <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἐμοῖς</span> <span class=\"greek\">λόγοις</span>, El. 886; Pla., Phd. 88c, Leg. 7, 798d; Polyb. 5, 42, 9; 9, 33, 1; Herodian 7, 5, 5 <span class=\"greek\">ἐλπίδι</span> <span class=\"greek\">κρείττονι</span>; BGU 674, 6 <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span>; 2 Ch 9:6 <span class=\"greek\">τοῖς</span> <span class=\"greek\">λόγοις</span>; Ps 105:24; Pr 14:15; Sir 19:15; En 104:13 <span class=\"greek\">ταῖς</span> <span class=\"greek\">βίβλοις</span>; Philo, Leg. All. 3, 229 <span class=\"greek\">τοῖς</span> <span class=\"greek\">κενοῖς</span> <span class=\"greek\">λογισμοῖς</span>, Virt. 68, palavras de Deus; Jos., C. Ap. 2, 286, Ant. 10, 39 <span class=\"greek\">τ</span>. <span class=\"greek\">λόγοις</span>; Tat. 18, 2 <span class=\"greek\">ὕλης</span> <span class=\"greek\">οἰκονομία</span>; Ath. 30, 2 <span class=\"greek\">ταῖς</span> <span class=\"greek\">γοναῖς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Διό</span>; Iren. 1, 10, 2 [Harv. I 92, 4] <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐκκλησία</span> … <span class=\"greek\">π</span>. <span class=\"greek\">τούτοις</span> [isto é, <span class=\"greek\">κήρυγμα</span> e <span class=\"greek\">πίστις</span>]): <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπίστευσας</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">μου</span> «não acreditaste em minhas palavras» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:20</a> (cf. Iambl., ViPyth. 28, 148 <span class=\"greek\">περὶ</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">θαυμαστὸν</span> <span class=\"greek\">ἀπιστεῖν</span>, «acerca dos deuses, nada é tão maravilhoso que suscite incredulidade»). <span class=\"greek\">τῇ</span> <span class=\"greek\">γραφῇ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:22</a>. Cf. 4:50; 5:47ab. <span class=\"greek\">τοῖς</span> <span class=\"greek\">γεγραμμένοις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:14</a> (Diod S 16, 52, 7 <span class=\"greek\">πιστεύσαντες</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">γεγραμμένοις</span>). <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐπαγγελίᾳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> 2 Cl 11:1 (Diod S 1, 53, 10 <span class=\"greek\">τῇ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">προρρήσει</span> <span class=\"greek\">πιστεύειν</span>; 19, 90, 3). <span class=\"greek\">τῷ</span> <span class=\"greek\">ψεύδει</span>, <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀληθείᾳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:11</a>, 12. <span class=\"greek\">τῇ</span> <span class=\"greek\">καταλαλιᾷ</span> Hm 2:2. <span class=\"greek\">τῇ</span> <span class=\"greek\">ἀκοῇ</span> <span class=\"greek\">ἡμῶν</span> (Is 53:1; cf. Jos., C. Ap. 2, 14 <span class=\"greek\">π</span>. <span class=\"greek\">ἀκοῇ</span> <span class=\"greek\">πρεσβυτέρων</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:16</a>; 1 Cl 16:3. <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔργοις</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 10:38b</a> (= seu testemunho); Hm 6, 2, 10a (que são bons e devem ser seguidos).—Passivo: <span class=\"greek\">ἐπιστεύθη</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">μου</span> «creram na minha palavra» Hm 3:3.<br><span class=\"greek\">ε</span>. Por expressões preposicionais: <span class=\"greek\">εἰς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:18</a>, se <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">γενέσθαι</span> <span class=\"greek\">αὐτόν</span> depende aqui de <span class=\"greek\">ἐπίστευσεν</span>. <span class=\"greek\">πιστεύειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">μαρτυρίαν</span> «crer no testemunho» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:10</a>c. <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστιανισμὸς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Ἰουδαϊσμὸν</span> <span class=\"greek\">ἐπίστευσεν</span> «a vida cristã, ou cristianismo, não se comprometeu com a vida judaica, ou judaísmo» (veja Hdb. ad loc.) I Mg 10:3a; cf. b (<span class=\"greek\">Χριστιανισμόν</span>, <span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ν</span> <span class=\"greek\">πᾶσα</span> <span class=\"greek\">γλῶσσα</span> <span class=\"greek\">πιστεύσασα</span>). Sobre <span class=\"greek\">πιστεύειν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομά</span> <span class=\"greek\">τινος</span>, veja 2a<span class=\"greek\">β</span> adiante. <span class=\"greek\">πιστεύετε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">εὐαγγελίῳ</span> «crede no evangelho» (assim Ps 105:12 <span class=\"greek\">ἐπίστευσαν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">αὐτοῦ</span>; antes no sentido de «depositar confiança em» Sir 32:21 <span class=\"greek\">μὴ</span> <span class=\"greek\">πιστεύσῃς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὁδῷ</span> <span class=\"greek\">ἀπροσκόπῳ</span>. Veja B-D-F §187, 6; Rob. 540. ALoisy, Les Évangiles synopt. I 1907, 430; 434; comentários) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:15</a> (Hofmann interpreta como «com base em»; Wohlenberg como «junto de»; Lohmeyer permanece indeciso; Dssm. e Mlt. 67s., «na esfera de»; veja p. 235). <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">εὐαγγελίῳ</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">πιστεύω</span> IPhld 8:2 (veja Bihlmeyer ad loc.).—<span class=\"greek\">ἐπί</span> <span class=\"greek\">τινι</span>: <span class=\"greek\">πιστεύειν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">οἷς</span> <span class=\"greek\">ἐλάλησαν</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">προφῆται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 24:25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:33</a> (Is 28:16).<br>ⓑ Com a pessoa a quem se dá crédito ou em quem se acredita, no dativo (Demosth. 18, 10; Aristot., Rhet. 2, 14 p. 1390a, 32; Polyb. 15, 26, 6 <span class=\"greek\">τοῖς</span> <span class=\"greek\">εἰδόσι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀλήθειαν</span>; Herodian 2, 1, 10; PHib 72, 18; POxy 898, 29; PTebt 418, 15; Ex 4:1, 5; 3 Km 10:7; 2 Ch 32:15; Tob 2:14; Jer 47:14; JosAs 13:10; Philo, Praem. 49; Just., A I, 33, 5, D 7, 2 e outros): <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεασαμένοις</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐγηγερμένον</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπίστευσαν</span> «não acreditaram naqueles que o viram ressuscitado dentre os mortos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.16.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 16:14</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:25</a>, 32abc; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:31</a>; 16:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.20.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 20:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.46\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:46a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:12</a>; 26:27a (<span class=\"greek\">τ</span>. <span class=\"greek\">προφήταις</span>, como Jos., Ant. 11, 96); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:1</a>; Hm 6, 1, 2ab.<br>Também acerca de Jesus e de Deus, em quem se acredita no sentido de aceitar suas revelações sem dúvida nem contradição. Jesus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:42</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.38\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:38</a>, 46b; 6:30; 8:45, 46; 10:37, 38a. Deus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 5:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:3</a> (Gen 15:6), 17 <span class=\"greek\">κατέναντι</span> <span class=\"greek\">οὗ</span> <span class=\"greek\">ἐπίστευσεν</span> <span class=\"greek\">θεοῦ</span> (= <span class=\"greek\">κατέναντι</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ᾧ</span> <span class=\"greek\">ἐπίστευσεν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.23\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:23</a>; 1 Cl 10:6 (os três últimos, Gen 15:6). <span class=\"greek\">ὁ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">πιστεύων</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">ψεύστην</span> <span class=\"greek\">πεποίηκεν</span> <span class=\"greek\">αὐτόν</span> «quem não crê em Deus faz dele mentiroso» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:10b</a>. AcPl Ha 3, 7.<br>ⓒ Com pessoa e coisa acrescentadas, <span class=\"greek\">π</span>. <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> «acreditar em alguém no que diz respeito a alguma coisa» (X., Apol. 15 <span class=\"greek\">μηδὲ</span> <span class=\"greek\">ταῦτα</span> <span class=\"greek\">εἰκῇ</span> <span class=\"greek\">πιστεύσητε</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>) Hm 6, 2, 6.—Com dativo de pessoa seguido de <span class=\"greek\">ὅτι</span> (ApcEsdr 4:35 p. 29, 12 Tdf.): <span class=\"greek\">πιστεύετέ</span> <span class=\"greek\">μοι</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πατρί</span> «crede-me que estou no Pai» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.14.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 14:11a</a>. Cf. 4:21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:25</a>.<br>ⓓ Em uso absoluto (quando o contexto fornece o objeto etc.; cf. ParJer 7:19 <span class=\"greek\">γέγονε</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τοῦτο</span>, <span class=\"greek\">ἵνα</span> <span class=\"greek\">πιστεύσωσιν</span>): <span class=\"greek\">ἐάν</span> <span class=\"greek\">τις</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">εἴπῃ</span>· <span class=\"greek\">ἰδοὺ</span> <span class=\"greek\">ὧδε</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Χριστός</span>, <span class=\"greek\">μὴ</span> <span class=\"greek\">πιστεύσητε</span> «se alguém vos disser: eis aqui o Cristo, não acrediteis [nele ou nessa afirmação]» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:23</a>; cf. v. 26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.67\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:67</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:12a</a>b; 10:25s.; 12:47, variante textual; 14:29; 16:31; 19:35; 20:8, 25; cf. GJs 19:3. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.29\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:29a</a>b <span class=\"greek\">πιστεύσαντες</span> «os que, apesar disso, acreditaram [na realidade da ressurreição]»; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:4</a>; 26:27b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.11.18\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 11:18</a> <span class=\"greek\">πιστεύω</span> «acredito [que há divisões entre vós]»; 15:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:19b</a> «até os demônios creem nisso»; Jd 5. Passivo: <span class=\"greek\">καρδίᾳ</span> <span class=\"greek\">πιστεύεται</span> «com o coração [ou no coração] se crê [que Jesus ressuscitou dentre os mortos]» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:10</a>.<br>ⓔ Acreditar = deixar-se influenciar <span class=\"greek\">κατά</span> <span class=\"greek\">τινος</span> «contra alguém» Pol 6:1.<br>ⓕ <span class=\"greek\">πιστεύομαι</span> «sou acreditado, gozo de confiança» (X., An. 7, 6, 33; Diod S 5, 80, 4 <span class=\"greek\">τοῖς</span> <span class=\"greek\">μάλιστα</span> <span class=\"greek\">πιστευομένοις</span> <span class=\"greek\">ἐπηκολουθήσαμεν</span>; 17, 32, 1; 1 Km 27:12; Jos., Ant. 10, 114; PGM 12, 279 <span class=\"greek\">πιστευθήσῃ</span> = «serás acreditado»), acerca de Eva: <span class=\"greek\">παρθένος</span> <span class=\"greek\">πιστεύεται</span> «as pessoas acreditam que ela é virgem» Dg 12:8, ou talvez «uma virgem é confiada [a alguém sem receio]». Veja 3 abaixo.<br>② Confiar-se a alguém com plena confiança, crer em, confiar, com implicação de compromisso completo com aquele em quem se confia. Em nossa literatura, Deus e Cristo são objetos dessa fé, que se apoia no poder deles e na proximidade de seu auxílio, além da convicção de que suas revelações são verdadeiras. O objeto é:<br>ⓐ Expresso:<br><span class=\"greek\">α</span>. Pelo dativo (cf. Soph., Philoct. 1374 <span class=\"greek\">θεοῖς</span> <span class=\"greek\">πιστ</span>.; X., Mem. 1, 1, 5; Ps.-Pla., Epinom. 980c <span class=\"greek\">πιστεύσας</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span> <span class=\"greek\">εὔχου</span>; Ptolem. Lagi [300 a.C.]: 138 Fgm. 8 Jac.; Maximus Tyr. 3, 8k <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἀπόλλωνι</span>; Epict., apêndice E, 10 p. 488 Sch. <span class=\"greek\">θεῷ</span>; Himerius, Or. 8 [= 23], 18 <span class=\"greek\">πῶς</span> <span class=\"greek\">Διονύσῳ</span> <span class=\"greek\">πιστεύσω</span> «como confiarei em Dioniso?»; UPZ 144, 12 [164 a.C.] <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῖς</span>; Jdth 14:10; Wsd 16:26; 4 Macc 7:21 e outros na LXX; Philo, Leg. All. 3, 229 <span class=\"greek\">πιστεύειν</span> <span class=\"greek\">θεῷ</span>, Rer. Div. Her. 92 <span class=\"greek\">μόνῳ</span> <span class=\"greek\">θεῷ</span>, Op. M. 45, Sacr. Abel. 70 <span class=\"greek\">τῷ</span> <span class=\"greek\">σωτήρι</span> <span class=\"greek\">θεῷ</span>, Abr. 269, Mos. 1, 225, Virt. 216 [sobre a fé em Fílon, veja Bousset, Rel.3 446ss.; EHatch, Essays in Biblical Gk. 1889, 83ss.; ASchlatter, D. Glaube im NT4 1927; EBréhier, Les idées philosophiques et religieuses de Philon d’Alexandrie 1908, 21925; HWindisch, Die Frömmigkeit Philos 1909, 23ss.; HWolfson, Philo ’47 I, 143–56, especialmente II, 215–18; WPeisker, D. Glaubensbegriff bei Philon, tese ’36]; Jos., Ant. 2, 117; 333; 3, 309; 20, 48, Bell. 3, 387 [veja ASchlatter, D. Theol. d. Judentums nach d. Bericht des Jos. ’32, 104ss.]; Just., A I, 18, 6 e outros).<br>Algumas passagens referidas em 1b acima, final, são repetidas, pois admitem classificação em ambos os sentidos com igual justificativa. Acerca de Deus: <span class=\"greek\">π</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> (Orig., C. Cels. 4, 89, 15) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:34</a>; 13:12 D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:8</a>; PtK 4 p. 16, 2; B 16:7; Hm 12, 6, 2; Hs 5, 1, 5. Cf. Hm 1:2; AcPl Ha 10, 13s. <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> (Sir 11:21; 2:8) Hv 4, 2, 6. <span class=\"greek\">οἱ</span> <span class=\"greek\">πιστεύσαντες</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> <span class=\"greek\">αὐτοῦ</span> Hs 9, 13, 5. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> seguido de <span class=\"greek\">ὅτι</span> Hm 9:7; cf. Hs 1:7.<br>Acerca de Cristo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:42</a>, variante textual (em lugar de <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτόν</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.30\" target=\"_blank\" rel=\"noopener noreferrer\">J 6:30</a> (<span class=\"greek\">σοί</span> = v. 29 <span class=\"greek\">εἰς</span> <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ν</span> <span class=\"greek\">ἀπέστειλεν</span> <span class=\"greek\">ἐκεῖνος</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.31\" target=\"_blank\" rel=\"noopener noreferrer\">J 8:31</a> (<span class=\"greek\">αὐτῷ</span> = v. 30 <span class=\"greek\">εἰς</span> <span class=\"greek\">αὐτόν</span>, mas veja Mlt. 67s.; JSwetnam defende aqui sentido de mais-que-perfeito: Biblica 61, ’80, 106–9); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.5.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 5:14</a>; 18:8a (ambos <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:14b</a> (<span class=\"greek\">οὗ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἤκουσαν</span> = <span class=\"greek\">τούτῳ</span> [aproximadamente equivalente a <span class=\"greek\">εἰς</span> <span class=\"greek\">τοῦτον</span>; cf. v. 14a] <span class=\"greek\">οὗ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἤκ</span>.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:12</a>; ITr 9:2; Hs 8, 3, 2.<br>Passivo, «ser objeto de crença» (X., Cyr. 4, 2, 8; 6, 1, 39; Pla., Lach. 181b; Ps.-Demosth. 58, 44 e outros; 1 Km 27:12; Just., D. 7, 3; Tat. 10, 2. Veja B-D-F §312, 1; também Rob. 815s.): <span class=\"greek\">ἐπιστεύθη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κόσμῳ</span> «foi objeto de fé no mundo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:16</a>.—<span class=\"greek\">π</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">υἱοῦ</span> «crer no nome do Filho», isto é, crer no Filho e aceitar aquilo que seu nome proclama sobre quem ele é, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">1J 3:23</a>.<br><span class=\"greek\">β</span>. Com <span class=\"greek\">εἰς</span> (cf. Hippol., Elench. 6, 19, 7 W. <span class=\"greek\">οἱ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Σίμωνα</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ἑλένην</span> <span class=\"greek\">πεπιστευκότες</span>; Just., D. 35, 8 e outros). Deus (BGU 874, 11 <span class=\"greek\">π</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span>): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:44b</a>; 14:1a (cf. ET 21, 1910, 53–57; 68–70; 138s.); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:21</a>, variante textual = Pol 2:1.—Cristo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:11</a>; 3:15, variante textual, 16, 18a, 36; 4:39; 6:29, 35, 40, 47, variante textual; 7:5, 31, 38s., 48; 8:30; 9:35s.; 10:42; 11:25, 26a, 45, 48; 12:11, 36 (<span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">φῶς</span>), 37, 42, 44a, 46; 14:1b, 12; 16:9; 17:20; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.43\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:43</a>; 14:23; 18:8 D; 19:4; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:14a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.29\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:10a</a>; AcPlCor 2:31; Hs 8, 3, 2.<br><span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄνομα</span> <span class=\"greek\">Ἰησοῦ</span> (ou <span class=\"greek\">αὐτοῦ</span> etc.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:12</a>; 2:23; 3:18c; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:13</a> (veja <span class=\"greek\">ὄνομα</span> 1d<span class=\"greek\">β</span> e 2a<span class=\"greek\">α</span> acima, final). <span class=\"greek\">π</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θάνατον</span> <span class=\"greek\">αὐτοῦ</span> «crer na sua morte» ITr 2:1. <span class=\"greek\">π</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">αἷμα</span> <span class=\"greek\">Χριστοῦ</span> «crer no sangue de Cristo» ISm 6:1.<br><span class=\"greek\">γ</span>. Com <span class=\"greek\">ἐπί</span> e dativo, acerca de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:17</a> D. De Cristo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:42</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:15</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.9.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 9:33</a>; 10:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:6</a> (os últimos três, Is 28:16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:16</a>.<br><span class=\"greek\">δ</span>. Com <span class=\"greek\">ἐπί</span> e acusativo (Wsd 12:2; Just., D. 46, 1 e outros), acerca de Deus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:34</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:5</a>, 24; PtK 3 p. 15, 12. De Cristo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:15</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.42\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:42</a>; 11:17; 16:31; 22:19.<br><span class=\"greek\">ε</span>. <span class=\"greek\">π</span>. <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> «crer em alguém» (Jer 12:6; Da 6:24 Theod.; Ps 77:22) é questionável em nossa literatura. Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:15</a> a melhor leitura é <span class=\"greek\">ἐν</span> <span class=\"greek\">αὐτῷ</span> e provavelmente deve ser construído com <span class=\"greek\">ἔχῃ</span> (em João, <span class=\"greek\">πιστεύω</span> costuma reger <span class=\"greek\">εἰς</span> quando exprime o objeto da fé, como em 3:16). Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:13</a>, as duas ocorrências de <span class=\"greek\">ἐν</span> <span class=\"greek\">ᾧ</span> provavelmente se ligam a <span class=\"greek\">ἐσφραγίσθητε</span> («em relação a quem fostes selados» [cf. 4:30]); ouvir e crer são ações coordenadas, e <span class=\"greek\">πιστεύσαντες</span>, assim como <span class=\"greek\">ἀκούσαντες</span>, é empregado absolutamente (assim REB; NRSV é menos claro). Veja, porém, 1a<span class=\"greek\">ε</span> acima: <span class=\"greek\">π</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">εὐαγγελίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:15</a>; IPhld 8:2.<br>ⓑ Objeto não expresso (<span class=\"greek\">πιστεύειν</span> absoluto em sentido transcendente: Aeschin., In Ctesiph. 1 <span class=\"greek\">ἐγὼ</span> <span class=\"greek\">πεπιστευκὼς</span> <span class=\"greek\">ἥκω</span> <span class=\"greek\">πρῶτον</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span>; Aristot., Rhet. 2, 17, 1391b, 1ss.; Plut., Mor. 170f; Porphyr., Ad Marcellam 24 <span class=\"greek\">πιστεῦσαι</span> <span class=\"greek\">δεῖ</span>, <span class=\"greek\">ὅτι</span> [= «porque»] <span class=\"greek\">μόνη</span> <span class=\"greek\">σωτηρία</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἐπιστροφή</span>; Herm. Wr. 9, 10ab <span class=\"greek\">ἐπίστευσε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καλῇ</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">ἐπανεπαύσατο</span>; cf. 1, 32 <span class=\"greek\">πιστεύω</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μαρτυρῶ</span> = PapBerl 9795 [RReitzenstein, Studien z. antiken Synkretismus 1926, p. 161, 2]; Num 20:12; Ps 115:1; Is 7:9; Sir 2:13; 1 Macc 2:59; Philo, Rer. Div. Her. 14; 101, Deus Imm. 4, Mut. Nom. 178; <span class=\"greek\">τότε</span> <span class=\"greek\">πιστεύσεις</span> <span class=\"greek\">θέλων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">θέλων</span> Theoph. Ant. 1, 8 [p. 74, 7]): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:32</a>; 16:16s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:12</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:7</a>, 50; 3:15, 18b; 4:41s., 48, 53; 5:44; 6:36, 47, 64ab, talvez 69 (MEnslin, The Perf. Tense in the Fourth Gosp.: JBL 55, ’36, 121–31, especialmente 128); 9:38; 10:26; 11:15, 40; 12:39; 20:31b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:4</a>; 8:13, 37a; 11:21; 13:12, 39, 48; 14:1; 15:5, 7; 17:12, 34; 18:8b, 27; 19:2; 21:25; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:16</a>; 3:22; 4:11; 10:4; 13:11; 15:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:21</a>; 3:5; 15:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:13</a>, 19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:10</a>, 13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:7</a>; 1 Cl 12:7; 2 Cl 17:3; 20:2; B 9:3; B 11:11; ISm 3:2; Hs 8, 10, 3; 9, 17, 4; 9, 22, 3. <span class=\"greek\">τὸ</span> <span class=\"greek\">πιστεύειν</span> «a fé» IMg 9:2. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγάπῃ</span> <span class=\"greek\">πιστεύειν</span> «crer com amor» IPhld 9:2 (<span class=\"greek\">ἐν</span> <span class=\"greek\">ἀγάπῃ</span> é aqui advérbio).<br>Particípios nos diversos tempos também são usados quase substantivamente: (<span class=\"greek\">οἱ</span>) <span class=\"greek\">πιστεύοντες</span> «os crentes, os cristãos» (Orig., C. Cels. 1, 13, 34; Did., Gen. 106, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:44</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:22a</a>b (em oposição a <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄπιστοι</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:7</a>; Hs 8, 3, 3. (<span class=\"greek\">οἱ</span>) <span class=\"greek\">πιστεύσαντες</span> «os que assumiram o compromisso», ou seja, «os que se tornaram crentes, os cristãos», <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.44\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:44</a>, variante textual; 4:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:10a</a>; 2 Cl 2:3; Hs 9, 19, 1. <span class=\"greek\">οἱ</span> <span class=\"greek\">πεπιστευκότες</span> «os que se tornaram, e permaneceram, crentes» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:18</a>; 21:20 (Just., D. 122, 2).—<span class=\"greek\">οἱ</span> <span class=\"greek\">μέλλοντες</span> <span class=\"greek\">πιστεύειν</span> «os futuros crentes» 1 Cl 42:4; Hm 4, 3, 3a. <span class=\"greek\">οἱ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">πιστεύσαντες</span> «os que acabam de crer» ibid. 4, 3, 3b.<br>ⓒ Uma forma especial dessa fé é a confiança de que Deus ou Cristo podem socorrer os suplicantes em sua aflição, «ter confiança» (algumas passagens já mencionadas poderiam ser classificadas igualmente aqui). Absoluto: <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐπίστευσας</span> <span class=\"greek\">γενηθήτω</span> <span class=\"greek\">σοι</span> «faça-se conforme a confiança que tens» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:13</a>. <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἂν</span> <span class=\"greek\">αἰτήσητε</span> <span class=\"greek\">πιστεύοντες</span> «tudo quanto pedirdes em oração com confiança» 21:22. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.36\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 5:36</a>; 9:23s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 8:50</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.4.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 4:13a</a> (Ps 115:1), b. Seguido de <span class=\"greek\">ὅτι</span>: <span class=\"greek\">πιστεύετε</span> <span class=\"greek\">ὅτι</span> <span class=\"greek\">δύναμαι</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">ποιῆσαι</span>; «confiais que sou capaz de fazer isto?» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:28</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:23</a>.<br>③ Confiar alguma coisa a alguém, <span class=\"greek\">τινί</span> <span class=\"greek\">τι</span> (X., Mem. 4, 4, 17; Plut., Mor. 519e; Athen. 8, 341a; Lucian, Dial. Deor. 25, 1; SIG2 845, 7; para muitos outros exemplos, veja índice VI p. 384b. Cf. Wsd 14:5; 1 Macc 8:16; 4 Macc 4:7; TestJob 11:11; Jos., Bell. 4, 492; Hippol., Ref. 9, 12, 6): <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀληθινὸν</span> <span class=\"greek\">τίς</span> <span class=\"greek\">ὑμῖν</span> <span class=\"greek\">πιστεύσει</span>; «quem vos confiará o verdadeiro?» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:11</a>. <span class=\"greek\">αὐτῷ</span> <span class=\"greek\">τοσούτων</span> <span class=\"greek\">πιστευο</span>̣<span class=\"greek\">μ</span>̣<span class=\"greek\">έ</span>̣<span class=\"greek\">ν</span>̣<span class=\"greek\">ω</span>̣<span class=\"greek\">ν</span>̣ «já que tantas coisas [ou tamanho encargo] lhe foram confiadas» AcPl Ha 7, 21 (conexão incerta). <span class=\"greek\">αὐτόν</span> (assim N. e Tdf.; variante textual <span class=\"greek\">ἑαυτόν</span>) <span class=\"greek\">τινι</span>, «confiar-se a alguém» (Brutus, Ep. 25; Plut., Mor. 181d <span class=\"greek\">ἀνδρὶ</span> <span class=\"greek\">μᾶλλον</span> <span class=\"greek\">ἀγαθῷ</span> <span class=\"greek\">πιστεύσας</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">ὀχυρῷ</span> <span class=\"greek\">τόπῳ</span> = «confiando-se antes a um homem bom do que a uma fortaleza»; EpArist 270; Jos., Ant. 12, 396) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:24</a> (EStauffer, CDodd Festschr., ’56, 281–99.—Diod S 34 + 35 Fgm. 39a <span class=\"greek\">οὐ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">τυχοῦσι</span> <span class=\"greek\">φίλοις</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">ἐπίστευσεν</span> = «não se confiou a amigos ocasionais»).<br>Passivo: <span class=\"greek\">πιστεύομαί</span> <span class=\"greek\">τι</span> (B-D-F §159, 4) «sou encarregado de algo» (Pla., Ep. 1, 309a; Polyb. 8, 17, 5; 31, 26, 7; Diod S 20, 19, 2; Appian, Bell. Civ. 2, 136 §568 <span class=\"greek\">ἃ</span> <span class=\"greek\">ἐπιστεύθην</span>; inscrições; papiros [por exemplo PLond I, 121, 608 p. 203]; Jos., Bell. 5, 567, Vi. 137; Ath. 24, 3. Cf. Esth 8:12e.—Dssm., LO 320s. [LAE 379]). <span class=\"greek\">ἐπιστεύθησαν</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">λόγια</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> «foram-lhes confiados os oráculos de Deus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:2</a>. <span class=\"greek\">πεπίστευμαι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">εὐαγγέλιον</span> «foi-me confiado o evangelho» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:7</a> (PGM 13, 140 <span class=\"greek\">ὁ</span> <span class=\"greek\">ὑπό</span> <span class=\"greek\">σου</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">πιστευθείς</span>; 446); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:11</a>.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:3</a>. <span class=\"greek\">οἰκονομίαν</span> <span class=\"greek\">πεπίστευμαι</span> «foi-me confiada uma administração» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:17</a>; cf. Dg 7:1. Veja também 7:2; IMg 6:1; IPhld 9:1ab. <span class=\"greek\">πιστεύομαί</span> <span class=\"greek\">τι</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span> «alguém me confia algo» (Polyb. 3, 69, 1; Jos., Bell. 1, 667): <span class=\"greek\">οἱ</span> <span class=\"greek\">πιστευθέντες</span> <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἔργον</span> <span class=\"greek\">τοιοῦτο</span> «aqueles a quem Deus confiou semelhante tarefa» 1 Cl 43:1.<br>④ Estar confiante acerca de algo, uso singular na expressão <span class=\"greek\">ὸ</span>̔<span class=\"greek\">ς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">πιστεύει</span> <span class=\"greek\">φαγεῖν</span> <span class=\"greek\">πάντα</span>, aproximadamente «um deles está confiante quanto a comer de tudo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:2</a> (combinam-se duas ideias: «a pessoa é forte na fé» e «está convencida de que lhe é lícito comer qualquer coisa»; resumindo, não tem escrúpulos cultuais sobre a comida. Veja Ltzm., Hdb. ad loc.; mas também B-D-F §397, 2).<br>Outra possibilidade é o sentido ⑤ achar, considerar (possível); em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:2</a>, talvez «julga que tudo é possível»; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">J 9:18</a> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπίστευσαν</span> «recusaram-se a considerar a possibilidade», e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:26</a>. Veja 4 acima.—Para bibliografia, veja <span class=\"greek\">πίστις</span>, final. DELG s.v. <span class=\"greek\">πείθομαι</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιστικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πιστικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">πίστις</span>; desde Pla., Gorg. 455a), empregado somente para qualificar <span class=\"greek\">νάρδος</span>, juntamente com <span class=\"greek\">πολυτελής</span> ou <span class=\"greek\">πολύτιμος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">J 12:3</a>; interpretado de diversas maneiras, mas evidentemente sugerindo qualidade extraordinária.<br>① Genuíno, não adulterado. Em autores posteriores, <span class=\"greek\">π</span>. designa aquilo que pertence a <span class=\"greek\">πίστις</span>, «fiel, digno de confiança» (Artem. 2, 32; Vett. Val. p. 10, 14; papiros, «pessoa de confiança»; Celsus 1, 39 <span class=\"greek\">λόγος</span> <span class=\"greek\">πιστικός</span>). Com base nisso, interpreta-se <span class=\"greek\">π</span>. como «genuíno, não adulterado» (Eus., Dem. Ev. 9, 8, 9 <span class=\"greek\">τοῦ</span> <span class=\"greek\">πιστικοῦ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καινῆς</span> <span class=\"greek\">διαθήκης</span> <span class=\"greek\">κράματος</span>; apresentado como possibilidade por Theophyl. Sim.; veja 3 abaixo. Consulte B-D-F §113, 2; Mlt-H. 379s.).<br>② A derivação de <span class=\"greek\">πίνω</span> (assim L-S-J-M), com o sentido «potável, líquido», é muito improvável (Frisk II 541).<br>③ Alguns derivam <span class=\"greek\">π</span>. de um nome de algum tipo (Theophyl. Sim. [MPG CXXIII 645b] <span class=\"greek\">πιστικὴν</span> <span class=\"greek\">νάρδον</span> <span class=\"greek\">νοεῖ</span> <span class=\"greek\">ἤτοι</span> <span class=\"greek\">εἶδος</span> <span class=\"greek\">νάρδου</span> <span class=\"greek\">οὕτω</span> <span class=\"greek\">λεγόμενον</span> <span class=\"greek\">πιστικὴν</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἄδολον</span> <span class=\"greek\">νάρδον</span>); por exemplo, da forma grega do latim spicatum (Galen XII 604 K. <span class=\"greek\">τὰ</span> <span class=\"greek\">πολυτελῆ</span> <span class=\"greek\">μύρα</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πλουσίων</span> <span class=\"greek\">γυναικῶν</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">καλοῦσιν</span> <span class=\"greek\">αὗται</span> <span class=\"greek\">σπίκατα</span>; outras referências em Wetstein sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:3</a>.—EbNestle, ZNW 3, 1902, 169ss.), ou de <span class=\"greek\">πιστάκια</span> «pistacheira» (AMerx sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:3</a>; MBlack, An Aramaic Approach3, ’67, 223–25), ou da forma indo-oriental picƷita, nome da planta Nardostachys Jatamansi.—UvWilamowitz, Reden u. Vorträge2 1902, 204; AJannaris, ClR 16, 1902, 9; RKöbert, Biblica 29, ’48, 279–81. W-S. §16, 3b nota 24. Veja também <span class=\"greek\">νάρδος</span>.—DELG s.v. <span class=\"greek\">πείθομαι</span>. M.M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πίστις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πίστις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (Hes., Hdt.+; varia semanticamente da confiança subjetiva à base objetiva da confiança).<br>① Aquilo que suscita confiança e fé.<br>ⓐ Estado de alguém em quem se pode depositar confiança, fidelidade, confiabilidade, lealdade, compromisso (X., An. 1, 6, 3; 3, 3, 4; Aristot., Eth. Eud, 7, 2, 1237b, 12; Polyb. 7, 12, 9; 38, 1, 8 e outros; Herodian 2, 14, 4 e outros; SIG 675, 22; OGI 557, 16; PTebt 27, 6; 51 [II a.C.]; POxy 494, 9; 705, 32; outros papiros em M-M. s.v.; Ps 32:4; Pr 12:22; Jos., Ant. 2, 61; TestAsh 7:7), com <span class=\"greek\">κρίσις</span> e <span class=\"greek\">ἔλεος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.23.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 23:23</a>. (Oposto a <span class=\"greek\">ἀπιστία</span>, como Hes., Op. 370), <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">καταργεῖν</span> «anular a fidelidade ou o compromisso de Deus» (cf. Ps 32:4; Hos 2:22) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:3</a>. <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἐνδείκνυσθαι</span> <span class=\"greek\">ἀγαθήν</span> «demonstrar toda boa fidelidade» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:10</a> (cf. BGU 314, 19 <span class=\"greek\">μετὰ</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">ἀγαθῆς</span>). Com outras virtudes, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:22</a> (sobre <span class=\"greek\">πίστις</span>, <span class=\"greek\">πραΰτης</span>, cf. Sir 45:4; 1:27). Com <span class=\"greek\">ὑπομονή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:4</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">τετήρηκα</span> «permaneci fiel ou leal» (<span class=\"greek\">πίστιν</span> <span class=\"greek\">τηρεῖν</span> como Polyb. 6, 56, 13; 10, 37, 5; Jos., Bell. 2, 121; 6, 345; OGI 339, 46s.; IBM III, 587b, 5s. [Dssm., LO 262 = LAE 309, especialmente nota 3]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:7</a>, embora alguns classifiquem essa ocorrência em 3 abaixo. Veja também 1c abaixo.<br>ⓑ Promessa solene de fidelidade e lealdade, garantia, juramento, compromisso (X., Cyr. 7, 1, 44; 8, 8, 3, Hell. 1, 3, 12; Diod S 14, 9, 7; Appian, Bell. Civ. 4, 86 §362 <span class=\"greek\">μεγάλας</span> <span class=\"greek\">πίστεις</span> <span class=\"greek\">ἔδωκεν</span> = «deu garantias solenes»; 3 Macc 3:10; Jos., Ant. 12, 382), <span class=\"greek\">τὴν</span> <span class=\"greek\">πρώτην</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἠθέτησαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 5:12</a> (veja também <span class=\"greek\">ἀθετέω</span> 1 e cf. CIA, apêndice [Wünsch, Praef. p. xv], acerca de mulher que <span class=\"greek\">πρώτη</span> <span class=\"greek\">ἠθέτησεν</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span> devida a seu marido). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:3</a>.<br>ⓒ Sinal oferecido como garantia de promessa, prova, penhor (Pla., Phd. 70b; Isocr. 3, 8; Aristot., Rhet. 1, 1; 3, 13; Epicurus em Diog. L. 10, 63; 85: <span class=\"greek\">πίστις</span> <span class=\"greek\">βεβαία</span> = «prova confiável»; Polyb. 3, 100, 3; <span class=\"greek\">Περὶ</span> <span class=\"greek\">ὕψους</span> 39, 3 = p. 74, 20 V.; Epict. 1, 28, 3; Appian, Bell. Civ. 4, 119 §500; Jos., Ant. 15, 69): <span class=\"greek\">πίστιν</span> <span class=\"greek\">παρασχὼν</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">ἀναστήσας</span> <span class=\"greek\">αὐτόν</span> «(Deus designou um homem [Jesus] para julgar o mundo e) ofereceu a todos a prova (de sua aptidão para essa função) ressuscitando-o» (sobre <span class=\"greek\">πίστιν</span> <span class=\"greek\">παρέχειν</span>, cf. Jos., Ant. 2, 218 <span class=\"greek\">πίστιν</span> <span class=\"greek\">παρεῖχε</span>; 15, 260; Polyb. 2, 52, 4 <span class=\"greek\">πίστιν</span> <span class=\"greek\">παρέσχετο</span> = «deu um penhor, uma garantia»; Vett. Val. 277, 29s.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:31</a>. JBarton, Biblica 40, ’59, 878–84: <span class=\"greek\">π</span>. em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:7</a> = «garantia depositada por um atleta». Mas veja 3 abaixo.—WSchmitz, <span class=\"greek\">῾Η</span> <span class=\"greek\">Πίστις</span> in den Papyri, tese, Colônia, ’64.<br>② Estado de quem acredita com fundamento na confiabilidade de quem é objeto da confiança, confiança, fé em sentido ativo, o ato de «crer», em relação à divindade (Soph., Oed. R. 1445 <span class=\"greek\">νῦν</span> <span class=\"greek\">γ</span>’ <span class=\"greek\">ἂν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">φέροις</span>; Pla., Leg. 12, 966de; Plut., Mor. 402e; 756b; Dio Chrys. 3, 51 <span class=\"greek\">παρὰ</span> <span class=\"greek\">θεῶν</span> <span class=\"greek\">τιμὴ</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πίστις</span>; Ael. Aristid. 13 p. 226 D.: <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῖς</span> <span class=\"greek\">ἔχειν</span>; Appian, Liby. 57 §248 <span class=\"greek\">ἐς</span> <span class=\"greek\">θεοὺς</span> <span class=\"greek\">πίστις</span>; Ep. 33 de Apollonius of Tyana [Philostrat. I 352, 14]; Herm. Wr. 9, 10 <span class=\"greek\">ἐπίστευσε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καλῇ</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">ἐπανεπαύσατο</span>; Porphyr., Ad Marcellam 21 <span class=\"greek\">τῆς</span> <span class=\"greek\">βεβαίας</span> <span class=\"greek\">πίστεως</span>, <span class=\"greek\">τὸ</span> <span class=\"greek\">μεμαθηκέναι</span>, <span class=\"greek\">ὅτι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">προνοεῖται</span> <span class=\"greek\">πάντα</span>. A divindade <span class=\"greek\">Πίστις</span> em Plut., Num. 70 [16, 1] e na magia [exemplos em Rtzst., Mysterienrel.3 234s., entre os quais Aberciusins. 12; PGM 4, 1014 <span class=\"greek\">ἀλήθεια</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πίστις</span>; 12, 228]; Wsd 3:14; 4 Macc 15:24; 16:22; 17:2; Philo, Abr. 270; 271; 273, Mut. Nom. 182, Migr. Abr. 43s., Conf. Lingu. 31, Poster. Cai. 13 [sobre a fé em Fílon, veja a bibliografia em <span class=\"greek\">πιστεύω</span> 2a<span class=\"greek\">α</span>]; Jos., C. Ap. 2, 163; 169; Just., A I, 52, 1 <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἔχειν</span>; 53, 11 <span class=\"greek\">πειθὼ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πίστιν</span> … <span class=\"greek\">ἐμφορῆσαι</span>), em nossa literatura dirigida a Deus e a Cristo, suas revelações, ensinamentos, promessas, poder e disposição para auxiliar.<br>ⓐ Deus: <span class=\"greek\">πίστις</span> <span class=\"greek\">θεοῦ</span> (cf. Jos., Ant. 17, 179.—Cf. <span class=\"greek\">π</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">φόβος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> Theoph. Ant. 1, 7 [p. 72, 26]), «fé, confiança em Deus» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 11:22</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 19:20</a> D; 1 Cl 3:4; 27:3. <span class=\"greek\">π</span>. <span class=\"greek\">θείου</span> <span class=\"greek\">πνεύμαπος</span> «fé no Espírito divino» Hm 11:9. <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> Hs 6, 3, 6. <span class=\"greek\">π</span>. (<span class=\"greek\">καὶ</span> <span class=\"greek\">ἐλπὶς</span>) <span class=\"greek\">εἰς</span> <span class=\"greek\">θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:21</a>. <span class=\"greek\">π</span>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:1</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:8</a> (sobre a construção com <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θ</span>., cf. Philo, Abr. 268; 271; 273; Just., D. 121, 2 <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ἥλιον</span> <span class=\"greek\">π</span>.).<br><span class=\"greek\">πίστις</span> também pode ser caracterizada como fé em Deus apenas pelo contexto, sem palavras específicas: assim, acerca de personagens do Antigo Testamento (OT), Abraão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:5</a>, 9, 11–13, 16, 19s. (veja também 2d<span class=\"greek\">α</span> adiante); 1 Cl 10:7; 31:2; Raabe 12:1, 8; Ester 55:6 (<span class=\"greek\">ἡ</span> <span class=\"greek\">τελεία</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">πίστιν</span>). Os heróis da fé do Antigo Testamento (OT), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:4</a>–33, 39 (compare-se esse catálogo com Il. 4, 457–538; 2 Km 23:8–39; 1 Ch 11:10–12:18; CGordon, Homer, and the Bible: HUCA 26, ’55, 83).—Mas também em Hebreus é Deus especificamente o objeto da fé cristã, e Cristo em 12:2 é <span class=\"greek\">ὁ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">ἀρχηγὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τελειώτης</span>. Cf. 10:38; 11:3; 13:7. (Sobre fé em Hebreus, veja Schlatter, Der Glaube im NT4 1927, 520ss.; BHeigl, Verfasser u. Adresse des Hb 1905, 109–18; GHoennicke, Die sittl. Anschauungen des Hb: ZWT 45, 1902, 26ss.; Windisch, Hdb., comentário sobre Hb 11; Riggenbach e Michel sobre Hb 11; Strathmann sobre 10:38. Veja <span class=\"greek\">ὑπόστασις</span>, final.)—<span class=\"greek\">ἐὰν</span> <span class=\"greek\">ἔχητε</span> <span class=\"greek\">πίστιν</span> «se tiverdes fé» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:20</a>. Oposto a dúvida, 21:21. <span class=\"greek\">αἰτεῖν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">διακρινόμενος</span> «pedir com fé, sem duvidar» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:6</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">εὐχὴ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> «a oração da fé» 5:15 (<span class=\"greek\">εὐχή</span> 1). <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐνεργείας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐγείραντος</span> <span class=\"greek\">αὐτὸν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">νεκρῶν</span> «fé na ação de Deus, que o ressuscitou dentre os mortos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:12</a>.<br>ⓑ Cristo.<br><span class=\"greek\">α</span>. Acerca de crer e confiar no auxílio do Senhor em aflições físicas ou espirituais, frequentemente nos evangelhos sinóticos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:10</a>; 9:2, 22, 29 (<span class=\"greek\">κατὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">ὑμῶν</span>); 15:28; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:5</a>; 4:40; 5:34; 10:52; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:20</a>; 7:9, 50; 8:25, 48; 17:19; 18:42.—Cf. <span class=\"greek\">ἔχει</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σωθῆναι</span> «(o coxo) tinha fé que seria curado» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:9</a>.<br><span class=\"greek\">β</span>. Acerca da fé em Cristo, assinalada pelo acréscimo de certas palavras. Pelo genitivo objetivo (veja Just., D. 52, 4 <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">χριστοῦ</span>): <span class=\"greek\">πίστις</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">Χριστοῦ</span> «fé em Jesus Cristo» (e expressões semelhantes. Sobre a interpretação como genitivo objetivo, veja AHultgren, NovT 22, ’80, 248–63 [bibliografia]; resposta SWilliams, CBQ 49, ’87, 431–47), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:22</a>, 26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 2:16a</a>b, 20; 3:22; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 3:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:9a</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 14:12</a>; cf. 2:13 (<span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">μου</span> «fé em mim», o Filho do Homem); IMg 1:1.<br>(<span class=\"greek\">πίστις</span> <span class=\"greek\">Χριστοῦ</span> em Paulo é interpretado como genitivo subjetivo por JHaussleiter, Der Glaube Jesu Christi 1891, Was versteht Paulus unter christlichem Glauben?: Greifswalder Studien für HCremer 1895, 161–82, e GKittel, StKr 79, 1906, 419ss. Veja também Schläger, ZNW 7, 1906, 356–58; BLongenecker, NTS 39, ’93, 478–80 [bibliografia desde ’81]; DCampbell, JBL 113, ’94, 265–85; resposta BDodd, 114, ’95, 470–73.—ADeissmann, Paulus2 1925, 125s. [Paul, tradução de WWilson, 1926, 162ss.], fala de genitivo místico, «fé em Cristo». Igualmente HWeber, Die Formel ‘in Christo Jesu’: NKZ 31, 1920, 213ss., especialmente 231, 3; WWeber, Christusmystik 1924, 82. Veja também LAlbrecht, Der Glaube Jesu Christi 1921; OSchmitz, Die Christusgemeinschaft des Pls im Lichte seines Genetivgebr. 1924, 91–134; OHoltzmann, D. Glaube an Jes.: Stromata 1930, 11–25; GTaylor, JBL 85, ’66, 58–76: as passagens de Gálatas = fidelidade de Cristo como fiador. Cf. GHoward, HTR 60, ’67, 459–65; MHooker, NTS 35, ’89, 321–42.)<br>Por expressões preposicionais: <span class=\"greek\">πίστις</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">Χριστόν</span> (e expressões semelhantes), «fé em Cristo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:21</a>; 24:24; 26:18; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">Col 2:5</a> (Just., D. 40, 1).—Também <span class=\"greek\">πίστις</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> (e similares) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:26</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:4</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:15</a>; 1 Cl 22:1. Na expressão <span class=\"greek\">ἱλαστήριον</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">αἵματι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:25</a>, <span class=\"greek\">ἐν</span> <span class=\"greek\">κτλ</span>. provavelmente não se liga a <span class=\"greek\">πίστις</span>, mas a <span class=\"greek\">ἱλαστήριον</span> (veja Ltzm., Hdb. ad loc.; W-S. §20, 5d).—<span class=\"greek\">πίστις</span>, <span class=\"greek\">ἣν</span> <span class=\"greek\">ἔχεις</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κύριον</span> <span class=\"greek\">Ἰησοῦν</span> Phlm 5.—<span class=\"greek\">πίστις</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">ἡμῶν</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χριστοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:21</a> D; semelhantemente <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">αὐτοῦ</span> 3:16b (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:21</a>).—Jesus Cristo é chamado <span class=\"greek\">ἡ</span> <span class=\"greek\">τελεία</span> <span class=\"greek\">πίστις</span> ISm 10:2.<br>ⓒ <span class=\"greek\">πίστις</span> pode ser caracterizada ainda por genitivo objetivo da coisa: <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὀνόματος</span> <span class=\"greek\">αὐτοῦ</span> «fé no nome dele [Jesus]» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:16a</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">εὐαγγελίου</span> «fé no evangelho» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:27</a>. <span class=\"greek\">εὐαγγελίων</span> <span class=\"greek\">πίστις</span> Dg 11:6. <span class=\"greek\">πίστις</span> <span class=\"greek\">ἀληθείας</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:13</a>.<br>ⓓ <span class=\"greek\">πίστις</span> aparece geralmente sem objeto expresso, «fé», «compromisso firme».<br><span class=\"greek\">α</span>. Como verdadeira piedade, devoção genuína (Sextus 7a e 7; ParJer 6:7), que em nossa literatura significa ser cristão (<span class=\"greek\">τὸ</span> <span class=\"greek\">ἀληθινὸν</span> <span class=\"greek\">πάσχα</span> … <span class=\"greek\">πίστει</span> <span class=\"greek\">νονούμενον</span> Hippol., Ref. 8, 18, 1; Did., Gen. 54, 11): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:8</a> (veja Jülicher, Gleichn. 288); 22:32; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.6.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 6:5</a> = v. 8, variante textual; cf. 11:24.—6:7; 13:8; 14:22; 15:9; 16:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:5</a>, 8, 12, 17ab (<span class=\"greek\">ἐκ</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">πίστιν</span> não significa gradação [como, em certo sentido, Appian, Mithrid. 40 §154: Sula encontrou <span class=\"greek\">ἕτερον</span> <span class=\"greek\">ὅμοιον</span> <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἑτέρου</span> = «uma muralha, ou fortificação, após outra semelhante»] nem transição de um tipo a outro [Himerius, Or. = Ecl. 10, 6 <span class=\"greek\">ἐκ</span> <span class=\"greek\">ᾠδῆς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">ᾠδὴν</span> <span class=\"greek\">ἄλλην</span> <span class=\"greek\">μετέβαλον</span> = «passaram de um tipo de canto a outro»], mas expressa retoricamente que <span class=\"greek\">πίστις</span> é começo e fim; veja Ltzm., Hdb. ad loc., e uma inscrição funerária [ANock, Sallust. p. xxxiii, 94] <span class=\"greek\">ἐκ</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">γῆν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">βίος</span> <span class=\"greek\">οὗτοσ</span> = «o pó é o começo e o fim da vida humana».—AFridrichsen, ConNeot 12, ’48, 54); 17c (aqui e em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:11</a> a LXX de Hab 2:4 [DCampbell, JBL 116, ’97, 713–19] não é seguida literalmente, pois traz <span class=\"greek\">ἐκ</span> <span class=\"greek\">πίστεώς</span> <span class=\"greek\">μου</span> = «em resultado de minha fidelidade»; mesmo em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.38\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:38</a>, onde ocorre <span class=\"greek\">μου</span>, esse pronome se relaciona com <span class=\"greek\">δίκαιος</span>, não com <span class=\"greek\">πίστεως</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 3:27</a>s. (o acréscimo da palavra «somente» por Lutero no v. 28 dificilmente pode ser contestado linguisticamente. Cf., por exemplo, Diog. L. 9, 6: Heráclito escreveu a obra em linguagem muito obscura <span class=\"greek\">ὅπως</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">δυνάμενοι</span> <span class=\"greek\">προσίοιεν</span> <span class=\"greek\">αὐτῷ</span> = «para que apenas os capazes se aproximassem». Veja também Fitzmyer, ABComm. 360–64), 30s.; 4:5–20 (veja também 2a acima); 5:1s.; 9:30, 32; 10:6, 17; 11:20 (em oposição a <span class=\"greek\">ἀπιστία</span>); 12:3, 6 (veja <span class=\"greek\">ἀναλογία</span>; para outra posição, 3 abaixo); 14:1, 22 (veja <span class=\"greek\">ἐνώπιον</span> 2b; outros colocariam em 2d<span class=\"greek\">ε</span>), 23ab (mas veja <span class=\"greek\">ε</span> abaixo); 16:26; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.2.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 2:5</a>; 15:14, 17; 16:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.24\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:24a</a>b; 4:13; 10:15; 13:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:7</a>–26; 5:5, 6 (veja <span class=\"greek\">ἐνεργέω</span> 1b); 6:10 (<span class=\"greek\">οἱ</span> <span class=\"greek\">οἰκεῖοι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>, veja <span class=\"greek\">οἰκεῖος</span> b); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 2:8</a>; 3:17; 4:5, 13; 6:16; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.1.25\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 1:25</a> (<span class=\"greek\">χαρὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span>); 2:17; 3:9b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:23</a>; 2:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:2</a>, 5, 7, 10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:3</a>, 11; 3:2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:2</a>, 4, 5 (<span class=\"greek\">π</span>. <span class=\"greek\">ἀνυπόκριτος</span>), 19ab; 4:1; 5:8; 6:10, 12, 21 (mas veja 3 abaixo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:5</a> (<span class=\"greek\">ἀνυπόκριτος</span> <span class=\"greek\">π</span>.); 2:18; 3:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:1</a>, 4, 13; 3:15; Phlm 6 (veja <span class=\"greek\">κοινωνία</span> 4); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:12</a>; 10:22, 39 (em oposição a <span class=\"greek\">ὑποστολή</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:3</a>; 2:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:5</a>, 7, 9; 5:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">1J 5:4</a>; 1 Cl 1:2 (<span class=\"greek\">ἡ</span> <span class=\"greek\">πανάρετος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">βεβαία</span> <span class=\"greek\">π</span>.); ISm 1:1 (<span class=\"greek\">ἀκίνητος</span> <span class=\"greek\">π</span>.); Hm 5, 2, 1; 12, 5, 4 (ambos <span class=\"greek\">πλήρης</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> «cheio de fé»); 5, 2, 3 (<span class=\"greek\">π</span>. <span class=\"greek\">ὁλόκληρος</span>); 9:6 (<span class=\"greek\">ὁλοτελὴς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">π</span>.), 7 (em oposição a <span class=\"greek\">διψυχία</span>), 12 (<span class=\"greek\">π</span>. <span class=\"greek\">ἡ</span> <span class=\"greek\">ἔχουσα</span> <span class=\"greek\">δύναμιν</span>); 12, 6, 1; Hs 9, 19, 2 (<span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. <span class=\"greek\">κενοί</span>); 9, 26, 8 (<span class=\"greek\">κολοβοὶ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. <span class=\"greek\">αὐτῶν</span>).<br>—<span class=\"greek\">τὸ</span> <span class=\"greek\">ῥῆμα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πίστεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:8</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγοι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:6</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">μυστήριον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">π</span>. 3:9. <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἤνοιξεν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔθνεσιν</span> <span class=\"greek\">θύραν</span> <span class=\"greek\">πίστεως</span> «Deus abriu aos gentios a porta da fé», isto é, abriu-lhes o caminho para participar de uma nova relação com Deus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:27</a> (veja também <span class=\"greek\">θύρα</span> 1b<span class=\"greek\">γ</span>). <span class=\"greek\">ἀκοὴ</span> <span class=\"greek\">πίστεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.2\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:2</a>, 5 (veja <span class=\"greek\">ἀκοή</span> 2 e 4b). (<span class=\"greek\">τὸ</span>) <span class=\"greek\">ἔργον</span> (<span class=\"greek\">τῆς</span>) <span class=\"greek\">π</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:11</a> (veja <span class=\"greek\">ἔργον</span> 1b). <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">πίστεως</span> «os da fé» (veja <span class=\"greek\">ἐκ</span> 3b) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:7</a>, 9. <span class=\"greek\">πῶς</span> <span class=\"greek\">οὐν</span> [<span class=\"greek\">πίστιν</span> <span class=\"greek\">εὑρ</span>]<span class=\"greek\">ίσκομεν</span>; Ox 1081, 25s. (mas a restauração [<span class=\"greek\">ταῦτα</span> <span class=\"greek\">γιγν</span>]<span class=\"greek\">ώ</span>̣<span class=\"greek\">σκομεν</span> é preferível, com Till, após o copta SJCh 90, 2); 32. Acerca de gnósticos, <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄφεως</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἔχουσιν</span> «têm fé na serpente» AcPlCor 2:20.<br>—Se o componente principal do cristianismo é fé, <span class=\"greek\">π</span>. pode ser entendido como o evangelho em termos do compromisso que desperta (cf. SIG 932, 7 [II/I a.C.]): <span class=\"greek\">νῦν</span> <span class=\"greek\">εὐαγγελίζεται</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">ἥν</span> <span class=\"greek\">ποτε</span> <span class=\"greek\">ἐπόρθει</span> «agora anuncia a fé que outrora procurava destruir» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:23</a> (veja 3 abaixo). Talvez também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:5</a>.<br><span class=\"greek\">β</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:1</a> define <span class=\"greek\">πίστις</span> como <span class=\"greek\">ἐλπιζομένων</span> <span class=\"greek\">ὑπόστασις</span>, <span class=\"greek\">πραγμάτων</span> <span class=\"greek\">ἔλεγχος</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">βλεπομένων</span>. Não há dúvida quanto ao sentido de <span class=\"greek\">π</span>. aqui como «confiança» ou «certeza» (veja 2a acima); quanto à relação com <span class=\"greek\">ὑπόστασις</span> como predicado, veja esse verbete.—(Ps.-Aristot., De Mundo 6, 18, interpreta <span class=\"greek\">πιστεύειν</span> em alguma coisa como incapacidade de ver aquilo que só é manifesto para Deus.) Paulo contrapõe o andar <span class=\"greek\">διὰ</span> <span class=\"greek\">εἴδους</span> (<span class=\"greek\">εἶδος</span> 3), como grau inferior, a <span class=\"greek\">διὰ</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">περιπατεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.5.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 5:7</a> (veja KDeissner, Pls. u. die Mystik seiner Zeit2 1921, 101ss.). Por outro lado, <span class=\"greek\">πίστις</span> encontra-se num grau mais alto do que a simples audição da pregação cristã, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 4:2</a>.<br><span class=\"greek\">γ</span>. <span class=\"greek\">πίστις</span> em uso absoluto, como virtude cristã, é frequentemente associada a outras virtudes, sobretudo a <span class=\"greek\">ἀγάπη</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 3:6</a>; 5:8; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 1:13</a>; Phlm 5; B 11:8; IEph 1:1; 9:1; 14:1; 20:1; IMg 1:2; 13:1; IRo, inscrição; ISm, inscrição; 6:1; 13:2; AcPl Ha 8, 35. Com <span class=\"greek\">ἀγάπη</span> e outros substantivos abstratos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 8:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.23\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:23</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:15</a>; 4:12; 6:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:22</a>; 3:10; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:2</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:19</a>; IPhld 11:2; Pol 4:2; Hm 8:9; cf. Hv 3, 8, 2–5. A tríade <span class=\"greek\">πίστις</span>, <span class=\"greek\">ἐλπίς</span>, <span class=\"greek\">ἀγάπη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 13:13</a>; cf. também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:4</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 1:3</a>; 5:8; B 1:4 (sobre essa tríade, veja <span class=\"greek\">ἀγάπη</span> 1a<span class=\"greek\">α</span>). Apenas com <span class=\"greek\">ἐλπίς</span> (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:21</a>), 1 Cl 58:2. A <span class=\"greek\">ζωῆς</span> <span class=\"greek\">ἐλπίς</span> é chamada <span class=\"greek\">ἀρχὴ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">ἡμῶν</span> B 1:6.<br>Com <span class=\"greek\">ἀλήθεια</span> (TestLevi 8:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 2:7</a> (cf. a combinação POxy 70, 4s. [III d.C.]); 1 Cl 60:4. Com <span class=\"greek\">δικαιοσύνη</span> Pol 9:2. Com <span class=\"greek\">ὑπομονή</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 13:10</a>; com <span class=\"greek\">ὑπομ</span>. e outros termos abstratos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:5</a>s.; Pol 13:2 (cf. ainda os trechos anteriormente citados nesta seção: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 6:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:10</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 2:2</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:3</a> [<span class=\"greek\">α</span> acima]). Com <span class=\"greek\">γνῶσις</span> (Just., D. 69, 1) e outros, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 1:5</a>s. [veja acima]; D 10:2. <span class=\"greek\">ἵνα</span> <span class=\"greek\">μετὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">τελείαν</span> <span class=\"greek\">ἔχητε</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γνῶσιν</span> B 1:5. Com <span class=\"greek\">φόβος</span> e <span class=\"greek\">ἐγκράτεια</span> Hm 6, 1, 1.—(Distinguida de <span class=\"greek\">θεία</span> <span class=\"greek\">σοφία</span>: Orig., C. Cels. 6, 13, 23.)<br><span class=\"greek\">δ</span>. Fé como fidelidade ao ensino cristão. Essa perspectiva requer <span class=\"greek\">ἔργα</span> além da espécie de <span class=\"greek\">πίστις</span> que representa somente um aspecto da verdadeira piedade: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:14a</a>b, 17, 18abc, 20, 22ab, 24, 26 (<span class=\"greek\">ἔργον</span> 1a); Hv 3, 6, 5; Hs 8, 9, 1ab.<br><span class=\"greek\">ε</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 14:22</a> e 23: <span class=\"greek\">π</span>. como liberdade ou força na fé, convicção (veja Ltzm., Hdb. ad loc.; mas veja <span class=\"greek\">α</span> acima).<br><span class=\"greek\">ζ</span>. Além da <span class=\"greek\">πίστις</span> que todo cristão possui (veja 2d<span class=\"greek\">α</span> acima), Paulo menciona um dom especial de fé que pertence a poucos escolhidos, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 12:9</a>. Nesse caso, entende <span class=\"greek\">π</span>. como crença inabalável no poder de Deus para socorrer pessoas por milagres, a fé que «move montanhas» 13:2 (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:20</a>.—21:21; veja 2a acima). Esse tipo especial de fé pode ser o que os discípulos tinham em mente ao pedir <span class=\"greek\">πρόσθες</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">πίστιν</span> «acrescenta-nos fé» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:5</a>; cf. v. 6. <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">φερόμενος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Παυλος</span> AcPl Ha 5, 1.<br>③ Aquilo que é objeto de crença, corpo de fé, de crenças ou de ensino (Diod S 1, 23, 8 <span class=\"greek\">ἰσχυρὰν</span> <span class=\"greek\">πίστιν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀμετάθετον</span> = «um artigo de fé firme e inabalável» [a respeito de Orfeu e Dioniso]; Mel., HE 4, 26, 13; Ath. 8, 1; Iren. 1, 10, 2 [Harv. I, 92, 1]; Orig., C. Cels. 1, 42, 26; Did., Gen. 156, 23). Assim, claramente Jd 3 (<span class=\"greek\">τῇ</span> <span class=\"greek\">ἅπαξ</span> <span class=\"greek\">παραδοθείσῃ</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἁγίοις</span> <span class=\"greek\">πίστει</span>), 20 (<span class=\"greek\">τῇ</span> <span class=\"greek\">ἁγιωτάτῃ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">πίστει</span>.—<span class=\"greek\">ἅγιος</span> 1a<span class=\"greek\">α</span>). <span class=\"greek\">πίστις</span> <span class=\"greek\">θεοῦ</span> = «aquilo que, segundo a vontade de Deus, se deve crer» IEph 16:2.<br>—Essa objetivação do termo <span class=\"greek\">πίστις</span> já se encontra em Paulo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 1:23</a> (veja 2d<span class=\"greek\">α</span>, final), e talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:23</a>–25 (veja Ltzm., Hdb. ad loc.). ASeeberg, D. Katechismus der Urchristenheit 1903, 110s., entende dessa maneira <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:19</a>; 4:1, 6; 6:10, cf. 21; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:18</a>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:6</a> (mas veja <span class=\"greek\">ἀναλογία</span>) e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:7</a> também são interpretados assim por muitos.<br>—EBurton, ICC Gal 1921, 475–86; ASchlatter, D. Glaube im NT4 1927; APott, Das Hoffen im NT in seiner Beziehung zum Glauben1915; ANairne, The Faith of the NT 1920; RGyllenberg, Pistis 1922; WKümmel, D. Glaube im NT: ThBl 16, ’38, 209–21; Dodd 65–68; TTorrance, ET 68, ’57, 111–14; CMoule, ibid. 157.<br>—Sinóticos: TShearer, ET 69, ’57, 3–6.<br>—Especialmente sobre Paulo: BBartmann, Pls, die Grundzüge seiner Lehre u. die moderne Religionsgeschichte 1914; WMorgan, The Religion and Theology of Paul 1917; WHatch, The Pauline Idea of Faith in Its Relation to Jewish and Hellenistic Religion 1917; Ltzm., Hdb., comentário após <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.4.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 4:25</a>; FKnoke, Der christl. Glaube nach Pls 1922; ERohde, Gottesglaube u. Kyriosglaube bei Pls: ZNW 22, 1923, 43–57; EWissmann, Das Verh. v. <span class=\"greek\">πίστις</span> und Christusfrömmigkeit bei Pls 1926; MDibelius, Glaube u. Mystik b. Pls: Neue Jahrb. f. Wissensch. u. Jugendbildg. 7, ’31, 683–99; WMundle, D. Glaubensbegriff des Pls ’32 (p. xi–xvi, bibliografia extensa); RGyllenberg, Glaube b. Pls: ZWT 13, ’37, 612–30; MHansen, Om Trosbegrebet hos Pls ’37; LMarshall, Challenge of NT Ethics, ’47, 270–77; 298–300; RBultmann, Theologie des NT ’48, 310–26 (tradução inglesa de KGrobel I ’51, 314–30; sobre escritos joaninos II, 70–92, ’55); MMassinger, BiblSacra 107, ’50, 181–94 e outros. Veja também <span class=\"greek\">δικαιοσύνη</span> 3a.<br>—Sobre o quarto Evangelho: JBuswell, The Ethics of ‘Believe’ in the Fourth Gospel: BiblSacra 80, 1923, 28–37; JHuby, De la connaissance de foi chez S. Jean: RSR 21, ’31, 385–421; RSchnackenburg, D. Glaube im 4. Ev., tese, Breslau ’37; WHatch, The Idea of Faith in Christ. Lit. fr. the Death of St. Paul to the Close of the Second Century 1926.<br>—EGraesser, D. Glaube im Hebräerbrief, ’65.<br>—ABaumeister, D. Ethik des Pastor Hermae, 1912, 61–140.<br>—ESeidl, <span class=\"greek\">π</span>. in d. griech. Lit. (até os peripatéticos), tese, Innsbruck, ’53; HLjungman, Pistis, ’64; DLührmann, Pistis im Judent., ZNW 64, ’73, 19–38. Sobre a fé no judaísmo tardio, veja Bousset, Rel.3 534a (índice); também DHay, JBL 108, ’89, 4611–76; DLindsay, Josephus and Faith ’93. Sobre o conceito helenístico de <span class=\"greek\">πίστις</span>, Rtzst., Mysterienrel.3 234–36.—DELG s.v. <span class=\"greek\">πείθομαι</span>. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιστός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πιστός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (<span class=\"greek\">πείθω</span>; Hom.+).<br>① Relativo a ser digno de crédito ou confiança, confiável, fiel, seguro, que inspira confiança ou fé; aspecto passivo de <span class=\"greek\">πιστεύω</span> (Hom.+).<br>ⓐ Acerca de pessoas.<br><span class=\"greek\">α</span>. Acerca de seres humanos (e Cristo): <span class=\"greek\">δοῦλος</span> (1 Km 22:14; 2 Macc 1:2; OdeSol 11:22; Jos., Ant. 6, 256; SIG 910 A, 5 [cristão]; PLond II, 251, 14 p. 317 [IV d.C.] <span class=\"greek\">δούλους</span> <span class=\"greek\">πιστοὺς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀδράστους</span>): <span class=\"greek\">δοῦλε</span> <span class=\"greek\">ἀγαθὲ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πιστέ</span> «servo bom e fiel» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:21a</a>, 23a; cf. 24:45; Hs 5, 2, 2 <span class=\"greek\">πιστότατος</span> (variante textual <span class=\"greek\">πιστός</span>). <span class=\"greek\">οἰκονόμος</span> «administrador» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:2</a>. <span class=\"greek\">μάρτυς</span> (Pind., P. 1, 88; 12, 27; Pr 14:5, 25; Ps 88:38; Jer 49:5; Philo, Sacr. Abel. 17): <span class=\"greek\">ὁ</span> <span class=\"greek\">μάρτυς</span> <span class=\"greek\">μου</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πιστός</span> <span class=\"greek\">μου</span> «minha testemunha fiel» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:13</a> (<span class=\"greek\">μάρτυς</span> 3). Nesse «livro de mártires», Cristo é <span class=\"greek\">ὁ</span> <span class=\"greek\">μάρτυς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πιστὸς</span> (<span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀληθινός</span>) «a testemunha fiel [e verdadeira]» 1:5; 3:14; cf. 19:11 (a combinação de <span class=\"greek\">ἀληθινός</span> e <span class=\"greek\">πιστός</span> nas duas últimas passagens é como em 3 Macc 2:11). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:14</a>.<br><span class=\"greek\">πιστὸς</span> <span class=\"greek\">ἀρχιερεύς</span> «sumo sacerdote fiel ou confiável» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 2:17</a> (acerca de Cristo); cf. 3:2 (<span class=\"greek\">ἀρχιερέα</span> … <span class=\"greek\">πιστὸν</span> <span class=\"greek\">ὄντα</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ποιήσαντι</span> <span class=\"greek\">αὐτόν</span>). <span class=\"greek\">σύμβουλοι</span> <span class=\"greek\">πιστοί</span> «conselheiros fiéis» B 21:4. <span class=\"greek\">πιστοὶ</span> <span class=\"greek\">ἄνθρωποι</span> «pessoas confiáveis» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:2</a> (cf. Is 8:2; singular Tob 5:3 S; 10:6 S; ApcEsdr 2:2).<br>Paulo honra seus colaboradores com <span class=\"greek\">π</span>. como designação: Timóteo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 4:17</a>; Tíquico <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:7</a> (ambos <span class=\"greek\">πιστὸς</span> <span class=\"greek\">διάκονος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span>); Onésimo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">Col 4:9</a>; Epafras 1:7 (<span class=\"greek\">πιστὸς</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">διάκονος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span>). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 5:12</a> (<span class=\"greek\">διὰ</span> <span class=\"greek\">Σιλουανοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πιστοῦ</span> <span class=\"greek\">ἀδελφοῦ</span>).—Moisés foi <span class=\"greek\">πιστὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ὅλῳ</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">οἴκῳ</span> <span class=\"greek\">αὐτοῦ</span> «fiel em toda a sua casa» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:5</a> (Num 12:7). <span class=\"greek\">πιστόν</span> <span class=\"greek\">τινα</span> <span class=\"greek\">ἡγεῖσθαι</span> «considerar alguém digno de confiança» (Aristoph., Plut. 27) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:12</a> (cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:11</a>; veja <span class=\"greek\">β</span> adiante); veja PtK 3 p. 15, 18. <span class=\"greek\">γίνου</span> <span class=\"greek\">πιστός</span> «sê fiel» (<span class=\"greek\">γίνομαι</span> 7 e cf. Jos., Vi. 110, Ant. 19, 317) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:10</a>.<br>—<span class=\"greek\">πιστὸς</span> <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> «fiel, confiável em alguma coisa» (TestJos 9:2 <span class=\"greek\">π</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">σωφροσύνῃ</span>): <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀδίκῳ</span> <span class=\"greek\">μαμωνᾷ</span> «em assuntos relativos às riquezas injustas» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:11</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἀλλοτρίῳ</span> «em relação ao que pertence a outrem» v. 12. <span class=\"greek\">ὁ</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἐλαχίστῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πολλῷ</span> <span class=\"greek\">π</span>. <span class=\"greek\">ἐστιν</span> «quem é fiel em assunto muito pequeno também o é em um grande» v. 10; 2 Cl 8:5; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 19:17</a>. <span class=\"greek\">π</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span> «confiável em todos os aspectos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 3:11</a>. Também <span class=\"greek\">ἐπί</span> <span class=\"greek\">τι</span> «em relação a algo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:21b</a>, 23b.<br>—Quando Paulo declara em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:25</a> que o Senhor misericordiosamente lhe concedeu o privilégio de ser <span class=\"greek\">πιστός</span>, e faz disso fundamento de sua pretensão a ser ouvido respeitosamente, <span class=\"greek\">πιστός</span> dificilmente significa «crente» (veja 2 abaixo); antes, o apóstolo percebe ter sido chamado e comissionado em sentido especial em virtude da confiança que Deus deposita nele (<span class=\"greek\">πιστός</span> é quase um título, «homem de confiança, comissário», frequente nas inscrições de pessoas ilustres: ISyriaW 2022a; 2029; 2034; 2045s.; 2127s.; 2130; 2219; 2238–40; 2243; 2394; cf. SEG XLII, 1484, 1599.—Correspondente <span class=\"greek\">πίστις</span> = «posição de confiança»: Achilles Tat. 8, 15, 1 <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄρχοντες</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">ταύτην</span> <span class=\"greek\">ἔχοντες</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">πίστιν</span>).<br><span class=\"greek\">β</span>. Acerca de Deus como aquele em quem podemos depositar inteira confiança (Pind., N. 10, 54; Dt 7:9; 32:4; Is 49:7; PsSol 14:1; 7:10; Philo, Rer. Div. Her. 93, Sacr. Abel. 93, Leg. All. 3, 204): <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:9</a>; 10:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.5.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 5:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:23</a>; 11:11; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:9</a>; 1 Cl 60:1; ITr 13:3. <span class=\"greek\">π</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἐπαγγελίαις</span> «fiel às promessas» 1 Cl 27:1 (cf. Ps 144:13a <span class=\"greek\">πιστὸς</span> <span class=\"greek\">κύριος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">λόγοις</span> <span class=\"greek\">αὐτοῦ</span>). <span class=\"greek\">πιστός</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐπαγγειλάμενος</span> «é fiel aquele que prometeu», acerca de Deus, 2 Cl 11:6.—Também acerca do «Senhor» (Cristo), descrito da mesma maneira que Deus: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 3:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:13</a>.<br>ⓑ Acerca de coisas, especialmente palavras (Hdt. 8, 83; Pla., Tim. 49b; Aristot., Rhet. 2, 1, 1377b, 23; Polyb. 3, 9, 4; 15, 7, 1; Plut., Mor. 160e; Cass. Dio 37, 35; Jos., Ant. 19, 132; Just., D. 11, 2 <span class=\"greek\">διαθήκη</span>; Ath., R. 17 p. 69, 16 <span class=\"greek\">τὸ</span> <span class=\"greek\">πιστόν</span>; Aberciusins. 6 <span class=\"greek\">γράμματα</span> <span class=\"greek\">πιστά</span> [acerca de mestre divino]): <span class=\"greek\">πιστὸς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> (Dionys. Hal. 3, 23, 17; Dio Chrys. 28 [45], 3) «fiel, digna de confiança é a palavra» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:15</a>; 3:1; 4:9; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 2:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:8</a>; cf. 1:9 (JBover, Biblica 19, ’38, 74–79). <span class=\"greek\">οἱ</span> <span class=\"greek\">λόγοι</span> <span class=\"greek\">πιστοὶ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀληθινοί</span> «palavras fiéis e verdadeiras» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:5</a>; 22:6. Oposto a <span class=\"greek\">ψευδής</span> Hm 3:5ab. Sobre <span class=\"greek\">τὰ</span> <span class=\"greek\">ὅσια</span>, <span class=\"greek\">Δαυὶδ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πιστά</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:34</a>, veja <span class=\"greek\">ὅσιος</span> 3.—Acerca de água, «confiável» (isto é, não sujeita a secar subitamente; cf. Dt 28:59 <span class=\"greek\">νόσοι</span> <span class=\"greek\">πισταί</span>), perene, abundante B 11:5 (Is 33:16). <span class=\"greek\">πιστὸν</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">τι</span> «agir lealmente» 3J 5.<br>② Relativo a alguém que confia, confiante, que alimenta fé ou confiança; aspecto ativo de <span class=\"greek\">πιστεύω</span> (Aeschyl., Pers. 55, Prom. 916; Soph., Oed. Col. 1031; Pla., Leg. 7, 824; Cass. Dio 37, 12, 1; Just., A I, 53, 10 e outros); também «crente, cheio de fé, fiel» (cf. POxy 1380, 152 <span class=\"greek\">ὁρῶσί</span> <span class=\"greek\">σε</span> [= Isis] <span class=\"greek\">οἱ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πιστὸν</span> <span class=\"greek\">ἐπικαλούμενοι</span> [sobre isso, AFestugière, RB 41, ’32, 257–61]; Sextus 1; 8; Wsd 3:9; Sir 1:14, 24, variante textual; Ps 100:6; SibOr 3, 69; 724), acerca de personagens dignos do Antigo Testamento (OT): Abraão (frequentemente chamado <span class=\"greek\">πιστός</span>; cf. Philo, Post. Cai. 173 <span class=\"greek\">Ἀβρ</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">πιστὸς</span> <span class=\"greek\">ἐπώνυμος</span>; 2 Macc 1:2; 1 Macc 2:52; Sir 44:20) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:9</a>; 1 Cl 10:1. <span class=\"greek\">Νῶε</span> <span class=\"greek\">πιστὸς</span> <span class=\"greek\">εὑρεθείς</span> «Noé foi achado fiel» 9:4; Moisés 17:5; 43:1 (ambos Num 12:7); veja também 1a<span class=\"greek\">α</span> acima (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:5</a>).<br>Acerca de crentes em contraste com pessoas que duvidam Hm 11:1ab. Sobre a fé na ressurreição de Jesus: <span class=\"greek\">μὴ</span> <span class=\"greek\">γίνου</span> <span class=\"greek\">ἄπιστος</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">πιστός</span> «não sejas incrédulo, mas crente» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.27\" target=\"_blank\" rel=\"noopener noreferrer\">J 20:27</a>.<br>Sobre quem professa a fé cristã: «crente, um crente no Senhor, em Cristo, em Deus»: <span class=\"greek\">π</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">κυρίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:15</a>. Também <span class=\"greek\">π</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">κυρίῳ</span> Hm 4, 1, 4; <span class=\"greek\">π</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">Χριστῷ</span> <span class=\"greek\">Ἰησοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.1.1\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 1:1</a>; <span class=\"greek\">πιστοὶ</span> <span class=\"greek\">ἀδελφοὶ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Χρ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/COL.1.2\" target=\"_blank\" rel=\"noopener noreferrer\">Col 1:2</a>; <span class=\"greek\">δι</span>’ <span class=\"greek\">αὐτοῦ</span> (= <span class=\"greek\">Χριστοῦ</span>) <span class=\"greek\">πιστοὶ</span> (<span class=\"greek\">πιστεύοντες</span>, variante textual) <span class=\"greek\">εἰς</span> <span class=\"greek\">θεόν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:21</a>.<br>—O uso absoluto de <span class=\"greek\">πιστός</span> também significa «crente [em Cristo], cristão» e aparece tanto como adjetivo (Just., D. 110, 4) quanto como substantivo: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 16:1</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:10</a>; 5:16; 6:2ab; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:6</a>; 1 Cl 48:5; 62:3; 63:3; Hm 9:9; Hs 8, 7, 4; 8, 9, 1; 8, 10, 1; 9, 22, 1. <span class=\"greek\">οἱ</span> <span class=\"greek\">πιστοί</span> «os crentes, os cristãos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 12:3</a> D; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:3</a>, 12; IEph 21:2; IMg 5:2 (oposto a <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄπιστοι</span>); MPol 12:3; 13:2; AcPl Ha 7, 7 (cf. Just., D. 47, 2 <span class=\"greek\">τοῖς</span> <span class=\"greek\">Χριστιανοῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πιστοῖς</span>). <span class=\"greek\">οἱ</span> <span class=\"greek\">ἅγιοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πιστοὶ</span> <span class=\"greek\">αὐτοῦ</span> ISm 1:2. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">περιτομῆς</span> <span class=\"greek\">πιστοί</span> «os crentes ou cristãos israelitas» (veja <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:36</a>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.45\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:45</a>. Sem artigo (Orig., C. Cels., prólogo 6, 5) Dg 11:2, 5. <span class=\"greek\">νέοι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πίστει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πιστοί</span> «novos na fé, mas ainda assim crentes» Hv 3, 5, 4.—<span class=\"greek\">πιστὸς</span> <span class=\"greek\">εἶναι</span> «ser crente» IRo 3:2. <span class=\"greek\">ἐὰν</span> <span class=\"greek\">ᾖ</span> <span class=\"greek\">τις</span> <span class=\"greek\">πιστότατος</span> <span class=\"greek\">ἀνήρ</span> «ainda que alguém seja crente convicto» Hm 6, 2, 7.—LFoley, CBQ 1 ’39, 163–65.—B. 1167. New Docs 2, 94, com referências a inscrições cristãs. DELG s.v. <span class=\"greek\">πείθομαι</span>. M-M. ENDT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιστόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πιστόω</span> (<span class=\"greek\">πιστός</span>), 1.º aoristo passivo <span class=\"greek\">ἐπιστώθην</span> (palavra desde Hom. e outros; inscrições, LXX, EpArist, Philo; Jos., Bell. 4, 213, Ant. 15, 85; Ath.—Fora de nossa literatura ocorre principalmente na voz média, raramente na passiva e na ativa apenas em Thu. 4, 88; 2 Km 7:25; 1 Ch 17:14; 2 Macc 7:24; 12:25; Philo, Leg. All. 3, 206); em nossa literatura somente no 1.º aoristo passivo, com sentido ativo.<br>① Agir de modo fiel, mostrar-se fiel: <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> «demonstrar-se fiel a alguma coisa» 1 Cl 15:4 (Ps 77:37).<br>② Estar seguro de algo em virtude de sua confiabilidade, ter confiança, estar convencido (assim o 1.º aoristo passivo em Od. 21, 218; Soph., Oed. Col. 1039; EpArist 91): <span class=\"greek\">σὺ</span> <span class=\"greek\">μένε</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">οἷς</span> (= <span class=\"greek\">τούτοις</span>, <span class=\"greek\">ἃ</span>) <span class=\"greek\">ἔμαθες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐπιστώθης</span> «quanto a ti, permanece naquilo que aprendeste e de que te convenceste» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.14\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:14</a>. <span class=\"greek\">πιστωθέντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">λόγῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> (com <span class=\"greek\">πληροφορηθέντες</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀναστάσεως</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> <span class=\"greek\">Ἰ</span>. <span class=\"greek\">Χρ</span>.) «cheios de fé na palavra de Deus ou por meio dela» 1 Cl 42:3.—DELG s.v. <span class=\"greek\">πείθομαι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πιστῶς</h1><div class=\"entry-meta\"><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πιστῶς</span>, advérbio de <span class=\"greek\">πιστός</span> (desde Antiphon, Or. 2, 47; inscrições [SEG XLII, 1215, 6], papiros [PLond II, 301, 7s. p. 256: II d.C.]; 4 Km 16:2; Jos., C. Ap. 2, 44), relativo à confiabilidade, fielmente: <span class=\"greek\">στηρίζεσθαι</span> 1 Cl 35:5; <span class=\"greek\">φυλάσσειν</span> Dg 7:2.—M-M s.v. <span class=\"greek\">πιστός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πίων, πῖον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πίων</span>, <span class=\"greek\">πῖον</span>, genitivo <span class=\"greek\">πίονος</span> (Hom. e outros; LXX; Philo, Aet. M. 100; Jos., Bell. 4, 468; Sib Or 3, 639; Just., D. 28, 3), gordo: <span class=\"greek\">θυσία</span> «sacrifício» MPol 14:2 (com <span class=\"greek\">προσδεκτή</span>).—DELG s.v. <span class=\"greek\">πῖαρ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλανάω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλανάω</span>, futuro <span class=\"greek\">πλανήσω</span>; 1.º aoristo <span class=\"greek\">ἐπλάνησα</span>. Passivo: 1.º aoristo <span class=\"greek\">ἐπλανήθην</span>; perfeito <span class=\"greek\">πεπλάνημαι</span> (veja as quatro entradas seguintes; Hom., Aeschyl., Hdt.+; noção geral: sem objetivo fixo ou razão aparente).<br>① Fazer alguém desviar-se de um caminho determinado, voz ativa.<br>ⓐ Desencaminhar, fazer vaguear, <span class=\"greek\">τινά</span> «alguém» (Aeschyl., Prom. 573; Hdt. 4, 128 e outros), figuradamente: <span class=\"greek\">πλ</span>. <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὁδοῦ</span> «fazer alguém desviar-se do caminho correto» D 6:1 (sobre <span class=\"greek\">πλ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὁδοῦ</span>, cf. Dt 11:28; Wsd 5:6).<br>ⓑ Induzir ao erro, enganar, <span class=\"greek\">τινά</span> «alguém», sentido transitivo de 1a sem o detalhe imagético (Pla., Prot. 356d, Leg. 655d e outros; papiros, LXX; TestAbr A 20 p. 103, 17 [Stone p. 54, 17], a morte enganou Abraão; TestLevi 10:2; TestJud 15:5; GrBar 4:8; Just., D. 103, 6; Orig., C. Cels. 5, 5, 29; Hippol., Ref. 6, 20, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:4</a>s., 11, 24; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:5</a>s.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">1J 2:26</a>; 3:7; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:20</a>; 12:9; 13:14; 19:20; 20:3, 8, 10; IMg 3:2; IPhld 7:1a. <span class=\"greek\">πλ</span>. <span class=\"greek\">ἑαυτόν</span> «enganar a si mesmo» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1J 1:8</a>. Em uso absoluto, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:13a</a>.—Veja 2c<span class=\"greek\">δ</span> abaixo.<br>② Prosseguir sem senso de direção apropriada, extraviar-se, deixar-se desencaminhar, vaguear sem rumo; voz passiva frequentemente com sentido ativo.<br>ⓐ Literalmente (desde Il. 23, 321; Gen 37:15; PsSol 17:17; ParJer 5:9; ApcrEzk P 1 verso 12; Jos., Bell. 7, 160; Iren. 1, 8, 4 [Harv. I 73, 3]): <span class=\"greek\">ἐπὶ</span> (variante textual <span class=\"greek\">ἐν</span>) <span class=\"greek\">ἐρημίαις</span> <span class=\"greek\">πλανώμενοι</span> «vagueando por desertos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.38\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:38</a>. Acerca de ovelhas extraviadas (Ps 118:176), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:12a</a>b, 13. <span class=\"greek\">ὡς</span> <span class=\"greek\">πρόβατα</span> <span class=\"greek\">πλανώμενα</span> «como ovelhas desgarradas» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:25</a>, variante textual.<br>ⓑ Figuradamente, acerca de pessoas que se afastaram do caminho correto (cf. 1a): <span class=\"greek\">ὡς</span> <span class=\"greek\">πρόβατα</span> <span class=\"greek\">πλανώμενοι</span> «vagueando como ovelhas» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 2:25</a>. <span class=\"greek\">ὡς</span> <span class=\"greek\">πρόβατα</span> <span class=\"greek\">ἐπλανήθημεν</span> «andamos desgarrados como ovelhas» 1 Cl 16:6a (Is 53:6a; cf. também Ps 118:176). <span class=\"greek\">καταλείποντες</span> <span class=\"greek\">εὐθεῖαν</span> <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">ἐπλανήθησαν</span> «abandonando o caminho reto, desviaram-se» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:15</a>. <span class=\"greek\">ἄνθρωπος</span> … <span class=\"greek\">ἐπλανήθη</span> «cada pessoa ... desviou-se» 1 Cl 16:6b (Is 53:6b). <span class=\"greek\">πλανῶνται</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ταλαιπωροῦσιν</span> <span class=\"greek\">περιπατοῦντες</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ταῖς</span> <span class=\"greek\">ἀνοδίαις</span> «vagueiam e sofrem, caminhando por regiões sem trilhas» Hv 3, 7, 1 (<span class=\"greek\">ἐν</span> como Lucian, Calumn. 1 <span class=\"greek\">ἐν</span> <span class=\"greek\">σκότῳ</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.38\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:38</a>, variante textual).<br>ⓒ Figuradamente, sem o pormenor imagético de 2b (cf. 1b).<br><span class=\"greek\">α</span>. Desviar-se, estar iludido (Cebes 6, 3; 24, 2; Orig., C. Cels. 6, 79, 41) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.3\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:3</a> (Dio Chrys. 4, 115 <span class=\"greek\">πλανῶνται</span> … <span class=\"greek\">δεδουλωμέναι</span> <span class=\"greek\">ἡδοναῖς</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 5:2</a>; 1 Cl 39:7 (Job 5:2); 59:4; 2 Cl 15:1 (sobre a <span class=\"greek\">ψυχή</span> como em Pr 13:9a; Wsd 17:1); B 2:9; B 16:1. <span class=\"greek\">πλανῶνται</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">καρδίᾳ</span> «seus pensamentos se desviam» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:10</a> (Ps 94:10). <span class=\"greek\">τινὲς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀνθρώπων</span> <span class=\"greek\">ἐπλανήθησαν</span> … <span class=\"greek\">μὴ</span> <span class=\"greek\">εἰδότες</span> «mas algumas pessoas se desviaram ... por não saberem» Ox 1081, 21 (conforme restauração).<br><span class=\"greek\">β</span>. Afastar-se, <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span> «da verdade» (Theoph. Ant. 2, 14 [p. 136, 26]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.19\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:19</a> (cf. Wsd 5:6).<br><span class=\"greek\">γ</span>. Equivocar-se em seu julgamento, enganar-se (Isocr., Ep. 6, 10 e outros; Jos., Bell. 1, 209, Ant. 10, 19; PFlor 61, 16; 2 Macc 7:18; ApcEsdr 2:28 [p. 26, 22 Tdf.]; Ar. 4, 2 e outros; Hippol., Ref. 5, 8, 1; Theoph. Ant. 1, 11 [p. 82, 13]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:24</a>; Hv 2, 4, 1. <span class=\"greek\">πολὺ</span> <span class=\"greek\">πλανᾶσθε</span> «estais muito enganados» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:27</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">πλανᾶσθε</span> «não vos enganeis» (Epict. 4, 6, 23) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 6:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.6.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 6:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:16</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">πᾶσιν</span> <span class=\"greek\">πεπλανήμεθα</span> «estamos completamente enganados» B 15:6 (cf. Hero Alex. III p. 214, 2 <span class=\"greek\">ἐν</span> <span class=\"greek\">μηδενὶ</span> <span class=\"greek\">πλανᾶσθαι</span>).<br><span class=\"greek\">δ</span>. Ser enganado, ser induzido ao erro: <span class=\"greek\">πλανῶντες</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πλανώμενοι</span> «enganadores [de outros] e enganados [eles próprios]» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 3:13</a> (cf. Herm. Wr. 16, 16 <span class=\"greek\">ὁ</span> <span class=\"greek\">πλανώμενος</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πλανῶν</span>).—Deixar-se desencaminhar, enganar (veja Gildersleeve, Syntax I§167 sobre a passiva «permissiva»; Bel 7 Theod.; JosAs 13:10; Just., D. 118, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:24</a>, variante textual; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.47\" target=\"_blank\" rel=\"noopener noreferrer\">J 7:47</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.23\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:23</a>. <span class=\"greek\">μὴ</span> <span class=\"greek\">πλανᾶσθε</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.33\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:33</a>; IEph 16:1; IMg 8:1; IPhld 3:3. <span class=\"greek\">μηδεὶς</span> <span class=\"greek\">πλανάσθω</span> IEph 5:2; ISm 6:1. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">πλανᾶται</span> «o Espírito não é induzido ao erro» IPhld 7:1b. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄφεως</span> <span class=\"greek\">πλανᾶται</span> «ele é enganado pela serpente» ou «se deixa enganar pela serpente» Dg 12:6 (UPZ 70, 28 [152/151 a.C.] <span class=\"greek\">πλανώμενοι</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεῶν</span>; Alex. Aphr., Fat. 12 p. 180, 25 Br. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">φύσεως</span>).—Schmidt, Syn. I 547–62. DELG s.v. <span class=\"greek\">πλανάομαι</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλάνη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλάνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πλανάω</span>; Aeschyl., Hdt.+; BGU 1208, 6 [27/26 a.C.]; veja New Docs 2, 94 sobre o uso frequente nos papiros com o sentido de «engano»; PWisc II, 10 [III d.C.] «erro»; LXX; En 99:7; TestSol [personificada]; Test12Patr; JosAs 8:10; AscIs 2:10; 3:28; Philo; Jos., Ant. 4, 276; apologistas exceto Mel.; Orig.).<br>Em nossa literatura, somente como extensão figurada do sentido primário («andar errante, perambular», por exemplo Hdt. 1, 30 acerca de Sólon, que percorreu a terra em busca de novos conhecimentos): desviar-se do caminho da verdade, erro, ilusão, engano, fraude a que alguém está sujeito (Pla. e outros, também Diod S 2, 18, 8; Herm. Wr. 1, 28 <span class=\"greek\">οἱ</span> <span class=\"greek\">συνοδεύσαντες</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">πλάνῃ</span>; Tob 5:14 BA; Pr 14:8; Jer 23:17; Just., A I, 56, 3; com <span class=\"greek\">φαντασία</span> Theoph. Ant. 2, 8 [p. 118, 4]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.64\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:64</a>.<br>Acerca de uma concepção errônea de Deus, como se manifesta no politeísmo e resulta em degradação moral (Wsd 12:24; Ar. 2, 1 e outros; Just., D. 47, 1; Tat. 29, 1; Iren. 1, 1, 3 [Harv. I 11, 10]; Did., Gen. 217, 30) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.1.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 1:27</a>; cf. <span class=\"greek\">τερατεία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πλάνη</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">γοήτων</span> Dg 8:4 (Jos., Ant. 2, 286 <span class=\"greek\">κατὰ</span> <span class=\"greek\">γοητείαν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">πλάνην</span>). <span class=\"greek\">διὰ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">κόσμῳ</span> <span class=\"greek\">πλάνην</span> «por causa do engano no mundo» AcPl Ha 1, 15 (cf. Just., D. 113, 6 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πλάνης</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>).—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 4:14</a> (veja <span class=\"greek\">μεθοδεία</span>); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.11\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:11</a> (oposto a <span class=\"greek\">ἀλήθεια</span> no v. 10).<br><span class=\"greek\">ἡ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἀθέσμων</span> <span class=\"greek\">πλ</span>. «o erro dos inescrupulosos» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:17</a>; <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁμαρτωλῶν</span> «dos pecadores» B 12:10. Cf. IEph 10:2. <span class=\"greek\">ἡ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">ἀνομία</span> «a iniquidade do erro» B 14:5 (<span class=\"greek\">ἀνομία</span> 1). <span class=\"greek\">ἡ</span> <span class=\"greek\">πλ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">νῦν</span> <span class=\"greek\">καιροῦ</span> «o erro do tempo presente» B 4:1. <span class=\"greek\">παρείσδυσιν</span> <span class=\"greek\">πλάνης</span> <span class=\"greek\">ποιεῖν</span> «introduzir insidiosamente o engano» 2:10 (veja <span class=\"greek\">παρείσδυσις</span>). Com <span class=\"greek\">ἀπάτη</span> Dg 10:7; com <span class=\"greek\">ἀπώλεια</span> 2 Cl 1:7. <span class=\"greek\">ἡ</span> <span class=\"greek\">κενὴ</span> <span class=\"greek\">ματαιολογία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πολλῶν</span> <span class=\"greek\">πλάνη</span> «o falatório vazio e o erro da multidão» Pol 2:1. <span class=\"greek\">μῦθος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πλάνη</span> «mera história e ilusão» 2 Cl 13:3. <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πλάνῃ</span> <span class=\"greek\">ἀναστρεφόμενοι</span> «os que vivem no erro» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.18\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 2:18</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πλάνης</span> «o espírito do erro» (Test12Patr.—em oposição a <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθείας</span>: TestJudah 20:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">1J 4:6</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">πλάνης</span> <span class=\"greek\">ὁδοῦ</span> <span class=\"greek\">αὐτοῦ</span> «do desvio de seu caminho» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.20\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:20</a> (<span class=\"greek\">ὁδός</span> 3b).<br><span class=\"greek\">τῇ</span> <span class=\"greek\">πλάνῃ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Βαλαὰμ</span> <span class=\"greek\">μισθοῦ</span> <span class=\"greek\">ἐξεχύθησαν</span> «por ganho, entregaram-se completamente ao erro de Balaão» Jd 11 (veja <span class=\"greek\">μισθός</span> 1 e <span class=\"greek\">ἐκχέω</span> 3).—<span class=\"greek\">πλάνη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄφεως</span> «o engano da serpente» Dg 12:3 (cf. Just., D. 88, 4 e Hippol., Ref. 5, 6, 3) provavelmente não tem sentido ativo, «engano praticado pela serpente», mas indica o engano ou erro originado por ela; cf. 12:8.—B. 1185. DELG s.v. <span class=\"greek\">πλανάομαι</span>. M-M. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλάνης, ητος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλάνης</span>, <span class=\"greek\">ητος</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πλανάω</span>; Soph. e outros; X., Mem. 4, 7, 5; Dio Chrys. 30 [47], 8; Vett. Val. 64, 6; Philo; empréstimo no rabínico), Jd 13, variante textual. A palavra equivale em significado a <span class=\"greek\">πλανήτης</span>; veja esse verbete.—DELG s.v. <span class=\"greek\">πλανάομαι</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλανήτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλανήτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πλάνης</span>; Soph. e outros; Vett. Val. 65, 4; Hos 9:17; Jos., Ant. 3, 145; Tat.; Ath. 23, 2), errante, aquele que vagueia, empregado como substantivo e adjetivo em nossa literatura somente na combinação <span class=\"greek\">ἀστέρες</span> <span class=\"greek\">πλανῆται</span> (Aristot., Meteor. 1, 6; Plut., Mor. 604a; 905c s.; Ps.-Lucian, Astrol. 14, Salt. 7 e outros; PGM 7, 513, principalmente acerca dos planetas, que pareciam «vaguear» pelo céu entre as estrelas fixas), figuradamente, tendo por pano de fundo tradição como En 18:15s.: «estrelas errantes» Jd 13 (a variante textual <span class=\"greek\">πλάνητες</span> [veja <span class=\"greek\">πλάνης</span>] não é de modo algum rara em outra literatura, por exemplo X., Mem. 4, 7, 5; Aristot., Met. 342b, 28, precisamente nessa combinação).—Veja <span class=\"greek\">ἀστήρ</span>, final. DELG s.v. <span class=\"greek\">πλανάομαι</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0287-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πλάνος, ον</h1><div class=\"entry-meta\"><span>adjetivo e substantivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πλάνος</span>, <span class=\"greek\">ον</span> (<span class=\"greek\">πλανάω</span>; trágicos e outros; LXX, Philo, Joseph.), em nossa literatura somente em sentido figurado: relativo a fazer alguém enganar-se.<br>ⓐ Como adjetivo, desencaminhador, enganoso (assim Menand., Fgm. 288 Kö.; Theocr. 21, 43; Moschus 1, 28; 5, 10; Jos., Bell. 2, 259; Just., A II, 15, 1, D. 70, 5 e outros): <span class=\"greek\">πνεύματα</span> <span class=\"greek\">πλάνα</span> «espíritos enganadores» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 4:1</a> (cf. TestBenj 6:1; Just., D. 7, 3 e outros); <span class=\"greek\">τούτων</span> <span class=\"greek\">εἰδώλων</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">πλάνων</span> «essas imagens sedutoras» ApcPt Bodl.<br>ⓑ Como substantivo, <span class=\"greek\">ὁ</span> <span class=\"greek\">πλάνος</span> «enganador, impostor» (Diod S 34 + 35, Fgm. 2, 14; Vett. Val. 74, 18; Ps.-Clem., Hom. 4, 2), acerca de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.63\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:63</a> (cf. TestLevi 16:3). Com <span class=\"greek\">ὁ</span> <span class=\"greek\">ἀντίχριστος</span> 2J 7b; no plural, v. 7a. <span class=\"greek\">ὡς</span> <span class=\"greek\">πλάνοι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀληθεῖς</span> «considerados impostores e, contudo, verdadeiros» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 6:8</a>.—DELG s.v. <span class=\"greek\">πλανάομαι</span>. M-M. TW.</p></section></article>"};
